    <linearGradient id="seaG" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#ffab6b"/>
      <stop offset="0.25" stop-color="#e0687a"/>
      <stop offset="1" stop-color="#2c2150"/>
    </linearGradient>
    <linearGradient id="cloudG" x1="0" y1="0" x2="0" y2="1">
