      <stop offset="1" stop-color="#7d4a8f"/>
    </linearGradient>
    <linearGradient id="brassG" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0" stop-color="#fff0b0"/>
      <stop offset="0.35" stop-color="#e0a84a"/>
      <stop offset="0.7" stop-color="#b07020"/>
      <stop offset="1" stop-color="#6b3f0a"/>
    </linearGradient>
    <linearGradient id="roadG" x1="0" y1="0" x2="0" y2="1">
      <stop offset="0" stop-color="#3b2d4d"/>
