    </linearGradient>
  </defs>

  <!-- 天空与霞光 -->
  <rect width="800" height="500" fill="url(#skyG)"/>
  <circle cx="540" cy="285" r="150" fill="url(#glowG)"/>
  <circle cx="540" cy="285" r="52" fill="url(#sunG)"/>
  <g id="clouds"></g>

  <!-- 远山 -->
  <path d="M0 300 L0 292 Q60 268 120 290 Q170 278 225 296 L262 300 Z" fill="#2a1b3d" opacity="0.85"/>
  <path d="M600 300 L640 288 Q680 280 710 292 Q750 284 800 296 L800 300 Z" fill="#2a1b3d" opacity="0.8"/>

  <!-- 海面 -->
  <rect x="0" y="300" width="800" height="120" fill="url(#seaG)"/>
  <g id="sunRef"></g>
  <g id="waves"></g>

  <!-- 路面 -->
  <rect x="0" y="420" width="800" height="80" fill="url(#roadG)"/>
  <line x1="0" y1="420" x2="800" y2="420" stroke="#ffb27a" stroke-width="2" opacity="0.6"/>
  <line id="roadDash" x1="0" y1="462" x2="800" y2="462" stroke="#ffd58a" stroke-width="3"
        stroke-dasharray="24 20" opacity="0.6"/>
  <ellipse cx="330" cy="423" rx="180" ry="5" fill="#000" opacity="0.35"/>

  <!-- 车轮（辐条旋转） -->
  <g id="wheels"></g>

  <!-- 骑行者整体（轻微颠簸） -->
  <g id="rider">
    <!-- 车架 -->
    <g id="frame" stroke="#1f7a8c" stroke-width="6" stroke-linecap="round" fill="none">
      <line x1="240" y1="360" x2="320" y2="360"/>   <!-- 链叉 -->
      <line x1="320" y1="360" x2="302" y2="262"/>   <!-- 座管 -->
      <line x1="302" y1="262" x2="388" y2="285"/>   <!-- 上管 -->
      <line x1="320" y1="360" x2="388" y2="285"/>   <!-- 下管 -->
      <line x1="302" y1="262" x2="240" y2="360"/>   <!-- 座叉 -->
      <line x1="388" y1="285" x2="420" y2="360" stroke="#2b2d42"/> <!-- 前叉 -->
    </g>
    <path d="M290 258 Q302 250 316 256 L314 264 Q302 268 290 264 Z" fill="#1b1b26"/>

    <!-- 链盘与链条 -->
    <g id="chainG">
      <circle cx="320" cy="360" r="14" fill="none" stroke="#9aa4b2" stroke-width="3"/>
      <circle cx="330" cy="360" r="2.5" fill="#ffd166"/>
    </g>
    <line x1="320" y1="346" x2="240" y2="353" stroke="#8c96a6" stroke-width="2"/>
    <line x1="320" y1="374" x2="240" y2="367" stroke="#8c96a6" stroke-width="2"/>
    <circle cx="240" cy="360" r="7" fill="none" stroke="#9aa4b2" stroke-width="2.5"/>

    <!-- 曲柄、脚踏、腿、脚 -->
    <line id="crankA" x1="320" y1="360" x2="332" y2="360" stroke="#2b2d42" stroke-width="4" stroke-linecap="round"/>
    <line id="crankB" x1="320" y1="360" x2="308" y2="360" stroke="#2b2d42" stroke-width="4" stroke-linecap="round"/>
    <rect id="pedalA" x="325" y="358" width="14" height="4" rx="2" fill="#444a5c"/>
    <rect id="pedalB" x="301" y="358" width="14" height="4" rx="2" fill="#444a5c"/>
    <path id="legA" fill="none" stroke="#f08a2e" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>
    <path id="legB" fill="none" stroke="#f08a2e" stroke-width="7" stroke-linecap="round" stroke-linejoin="round"/>
    <ellipse id="footA" rx="7" ry="3" fill="#ff9a3c" stroke="#c75c12" stroke-width="0.8"/>
    <ellipse id="footB" rx="7" ry="3" fill="#ff9a3c" stroke="#c75c12" stroke-width="0.8"/>

    <!-- 鹈鹕 -->
    <g id="pelican">
      <!-- 尾羽 -->
      <path d="M262 236 C248 232 232 226 220 216 C230 220 240 222 248 222 C240 230 238 238 244 246 Z"
            fill="#f4f6fa" stroke="#c9ced8" stroke-width="1"/>
      <!-- 身体 -->
      <path d="M260 228 C262 200 290 188 314 194 C338 200 346 228 336 246 C322 262 284 264 270 252 C262 246 258 238 260 228 Z"
            fill="#fbfcfe" stroke="#c9ced8" stroke-width="1.5"/>
      <path d="M268 250 C284 264 322 262 336 246 C326 252 300 256 268 250 Z" fill="#d3dae5"/>
      <!-- 颈部 -->
      <path d="M326 206 C340 184 346 166 356 146" stroke="#c9ced8" stroke-width="22" stroke-linecap="round" fill="none"/>
      <path d="M326 206 C340 184 346 166 356 146" stroke="#fbfcfe" stroke-width="18" stroke-linecap="round" fill="none"/>
      <!-- 翅膀（拍动） -->
      <g id="wing">
        <path d="M284 206 C270 226 262 246 272 258 C292 260 324 244 338 220 C326 206 304 198 284 206 Z"
              fill="#eef1f6" stroke="#b9c1cf" stroke-width="1.2"/>
        <path d="M272 258 C290 250 312 240 328 226 M276 250 C294 244 312 234 326 222"
              stroke="#b9c1cf" stroke-width="1" fill="none"/>
      </g>
      <!-- 围巾 -->
      <g id="scarf">
        <path d="M336 196 Q348 206 356 192 L358 202 Q348 214 334 208 Z" fill="#e63946"/>
        <path id="scarfTail" d="M340 206 Q320 208 304 218 L306 226 Q324 218 344 214 Z" fill="#c1121f"/>
      </g>
      <!-- 头 -->
      <ellipse cx="360" cy="138" rx="17" ry="15" fill="#fbfcfe" stroke="#c9ced8" stroke-width="1.2"/>
      <!-- 喙 -->
      <path d="M372 130 C396 128 414 140 436 158 C414 156 396 152 374 146 Z"
            fill="#ffb14a" stroke="#d97a1a" stroke-width="1.5"/>
      <!-- 喉囊 -->
      <path d="M374 146 C396 152 410 160 420 166 C416 182 404 190 392 184 C384 176 378 164 374 146 Z"
            fill="#ff9d2e" stroke="#d97a1a" stroke-width="1.5"/>
      <!-- 眼睛 -->
      <circle cx="366" cy="134" r="3.2" fill="#1a1020"/>
      <circle cx="367" cy="133" r="1" fill="#fff"/>
    </g>

    <!-- 车把与铜铃 -->
    <path d="M388 285 L396 262 Q402 252 416 254" fill="none" stroke="#2b2d42" stroke-width="4" stroke-linecap="round"/>
    <g id="bell">
      <g id="bellBody">
        <rect x="394" y="249" width="22" height="3" rx="1.5" fill="#8a5a14"/>
        <path d="M396 250 C396 238 414 238 414 250 Z" fill="url(#brassG)" stroke="#6b3f0a" stroke-width="0.8"/>
        <path d="M400 243 Q403 240 406 242" stroke="#fff" stroke-width="1" fill="none" opacity="0.7"/>
        <circle cx="405" cy="253" r="2" fill="#4a2e08"/>
      </g>
      <g id="bellArcs" stroke="#ffd98a" stroke-width="1.4" fill="none" opacity="0">
        <path d="M421 240 Q426 246 421 252"/>
        <path d="M425 236 Q432 246 425 256"/>
        <path d="M389 240 Q384 246 389 252"/>
        <path d="M385 236 Q378 246 385 256"/>
      </g>
      <!-- 点击区域 -->
      <rect x="380" y="228" width="50" height="34" fill="transparent"/>
    </g>
  </g>
</svg>

<div class="bar">
  <span>点击铜铃可以摇响 ✦</span>
  <button id="pauseBtn">暂停</button>
</div>
</div>

<script>
(() => {
  const NS = 'http://www.w3.org/2000/svg';
  const SEED = 1866;
  const SPEED = 110;                // 骑行速度（像素/秒）

  // 可复现的伪随机数（mulberry32）
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ (a >>> 15), 1 | a);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }
  const rand = mulberry32(SEED);

  const $ = id => document.getElementById(id);
  function el(tag, attrs = {}, parent) {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }

  // ---------- 云 ----------
  const cloudsG = $('clouds');
  const clouds = [];
  for (let i = 0; i < 7; i++) {
    const g = el('g', { opacity: (0.35 + rand() * 0.35).toFixed(2) }, cloudsG);
    const s = 0.6 + rand() * 0.9;
    const parts = [[0, 0, 46], [30, -8, 34], [-30, -4, 30], [12, 8, 38]];
    parts.forEach(([dx, dy, r]) =>
      el('ellipse', { cx: dx * s, cy: dy * s, rx: r * s, ry: r * 0.42 * s, fill: 'url(#cloudG)' }, g));
    clouds.push({ g, x: rand() * 800, y: 50 + rand() * 150, sp: 6 + rand() * 10 });
  }

  // ---------- 霞光在海面的倒影 ----------
  const sunRefG = $('sunRef');
  const refs = [];
  for (let i = 0; i < 10; i++) {
    const e = el('ellipse', {
      cx: 540, cy: 318 + i * 11,
      rx: 44 - i * 3.6, ry: 2.2 + (i % 3) * 0.4,
      fill: '#ffe7a0', opacity: (0.85 - i * 0.07).toFixed(2)
    }, sunRefG);
    refs.push(e);
  }

  // ---------- 海浪 ----------
  const wavesG = $('waves');
  const waves = [];
  for (let i = 0; i < 70; i++) {
    const y = 304 + Math.pow(rand(), 0.8) * 112;
    const d = (y - 300) / 120;                      // 越近越大、越快
    const len = (10 + rand() * 46) * (0.4 + d * 0.9);
    const x = rand() * 820;
    const p = el('path', {
      d: `M0 0 H${len.toFixed(1)}`,
      stroke: rand() < 0.6 ? '#ffe2b0' : '#ffffff',
      fill: 'none',
      'stroke-width': (0.6 + d * 1.8).toFixed(2),
      'stroke-linecap': 'round',
      opacity: (0.25 + rand() * 0.5).toFixed(2)
    }, wavesG);
    waves.push({ p, x, y, len, sp: 25 + d * 170 });
  }

  // ---------- 车轮（辐条） ----------
  const wheelsG = $('wheels');
  function makeWheel(cx, cy, r) {
    const g = el('g', {}, wheelsG);
    el('circle', { cx, cy, r: r - 3, fill: 'none', stroke: '#15121f', 'stroke-width': 6 }, g);   // 轮胎
    el('circle', { cx, cy, r: r - 6, fill: 'none', stroke: '#8b96a8', 'stroke-width': 2 }, g);  // 轮圈
    const spokes = el('g', {}, g);
    for (let i = 0; i < 24; i++) {
      const a = i / 24 * Math.PI * 2;
      el('line', {
        x1: cx, y1: cy,
        x2: cx + Math.cos(a) * (r - 6), y2: cy + Math.sin(a) * (r - 6),
        stroke: '#dfe6f0', 'stroke-width': 1, opacity: 0.85
      }, spokes);
    }
    // 气门嘴（用于直观看出旋转）
    el('circle', { cx: cx + r - 6, cy, r: 2.2, fill: '#e63946' }, spokes);
    el('circle', { cx, cy, r: 6, fill: 'url(#brassG)' }, g);                                    // 铜色轮毂
    return spokes;
  }
  const rearSpokes = makeWheel(240, 360, 60);
  const frontSpokes = makeWheel(420, 360, 60);

  // ---------- 鹈鹕的翅膀与围巾 ----------
  const wing = $('wing');
  const scarfTail = $('scarfTail');

  // ---------- 腿部 IK ----------
  const HIP = { x: 302, y: 254 };
  const L1 = 66, L2 = 66;
  function legPath(foot) {
    let dx = foot.x - HIP.x, dy = foot.y - HIP.y;
    let d = Math.hypot(dx, dy);
    const maxD = L1 + L2 - 0.5;
    if (d > maxD) { const s = maxD / d; dx *= s; dy *= s; d = maxD; }
    const ux = dx / d, uy = dy / d;
    const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, L1 * L1 - a * a));
    const px = HIP.x + ux * a, py = HIP.y + uy * a;
    const c1 = [px - uy * h, py + ux * h];
    const c2 = [px + uy * h, py - ux * h];
    const knee = c1[0] > c2[0] ? c1 : c2;   // 膝盖朝前
    return `M${HIP.x} ${HIP.y} L${knee[0].toFixed(2)} ${knee[1].toFixed(2)} L${(HIP.x + dx).toFixed(2)} ${(HIP.y + dy).toFixed(2)}`;
  }

  const crankA = $('crankA'), crankB = $('crankB');
  const pedalA = $('pedalA'), pedalB = $('pedalB');
  const legA = $('legA'), legB = $('legB');
  const footA = $('footA'), footB = $('footB');
  const BB = { x: 320, y: 360 }, CR = 12;

  function drivePose(theta) {
    const pA = { x: BB.x + CR * Math.cos(theta), y: BB.y + CR * Math.sin(theta) };
    const pB = { x: BB.x - CR * Math.cos(theta), y: BB.y - CR * Math.sin(theta) };
    crankA.setAttribute('x2', pA.x.toFixed(2)); crankA.setAttribute('y2', pA.y.toFixed(2));
    crankB.setAttribute('x2', pB.x.toFixed(2)); crankB.setAttribute('y2', pB.y.toFixed(2));
    pedalA.setAttribute('x', (pA.x - 7).toFixed(2)); pedalA.setAttribute('y', (pA.y - 2).toFixed(2));
    pedalB.setAttribute('x', (pB.x - 7).toFixed(2)); pedalB.setAttribute('y', (pB.y - 2).toFixed(2));
    const fA = { x: pA.x, y: pA.y - 3 }, fB = { x: pB.x, y: pB.y - 3 };
    legA.setAttribute('d', legPath(fA));
    legB.setAttribute('d', legPath(fB));
    footA.setAttribute('cx', fA.x.toFixed(2)); footA.setAttribute('cy', fA.y.toFixed(2));
    footB.setAttribute('cx', fB.x.toFixed(2)); footB.setAttribute('cy', fB.y.toFixed(2));
  }

  // ---------- 铜铃 ----------
  const bellBody = $('bellBody');
  const bellArcs = $('bellArcs');
  const BELL_T = 0.9;
  let ringT = 0;
  let autoRingTimer = 4 + rand() * 3;

  let audioCtx = null;
  function ding() {
    try {
      audioCtx = audioCtx || new (window.AudioContext || window.webkitAudioContext)();
      const now = audioCtx.currentTime;
      const o = audioCtx.createOscillator();
      const g = audioCtx.createGain();
      o.type = 'sine';
      o.frequency.value = 2093;
      g.gain.setValueAtTime(0.25, now);
      g.gain.exponentialRampToValueAtTime(0.001, now + 1.4);
      o.connect(g).connect(audioCtx.destination);
      o.start(now);
      o.stop(now + 1.5);
    } catch (e) { /* 无音频环境时忽略 */ }
  }
  $('bell').addEventListener('click', () => { ringT = BELL_T; ding(); });

  // ---------- 暂停 ----------
  let paused = false;
  const pauseBtn = $('pauseBtn');
  pauseBtn.addEventListener('click', () => {
    paused = !paused;
    pauseBtn.textContent = paused ? '继续' : '暂停';
  });

  // ---------- 动画主循环 ----------
  const roadDash = $('roadDash');
  const chainG = $('chainG');
  const rider = $('rider');
  let t = 0, dist = 0, last = performance.now();

  function frame(now) {
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;

    if (!paused) {
      t += dt;
      dist += dt * SPEED;

      // 云漂移
      clouds.forEach(c => {
        c.x += c.sp * dt;
        if (c.x > 950) c.x = -150;
        c.g.setAttribute('transform', `translate(${c.x.toFixed(1)} ${c.y.toFixed(1)})`);
      });

      // 海浪（远处慢、近处快）
      waves.forEach(w => {
        w.x -= w.sp * dt;
        if (w.x + w.len < 0) w.x = 800 + rand() * 40;
        w.p.setAttribute('transform', `translate(${w.x.toFixed(1)} ${w.y.toFixed(1)})`);
      });
    }

    // 霞光倒影轻微晃动（始终进行）
    refs.forEach((e, i) => {
      const off = Math.sin(t * 1.6 + i * 0.7) * (3 + i * 0.6);
      e.setAttribute('cx', (540 + off).toFixed(2));
    });

    // 车轮与链盘
    const wheelDeg = dist / 60 * 180 / Math.PI;
    rearSpokes.setAttribute('transform', `rotate(${wheelDeg.toFixed(2)} 240 360)`);
    frontSpokes.setAttribute('transform', `rotate(${wheelDeg.toFixed(2)} 420 360)`);

    const crank = dist / 40;                          // 踏板角度（弧度）
    chainG.setAttribute('transform', `rotate(${(crank * 180 / Math.PI).toFixed(2)} 320 360)`);
    drivePose(crank);

    // 路面虚线
    roadDash.setAttribute('stroke-dashoffset', (-dist).toFixed(1));

    // 骑行颠簸（随踏板节奏）
    const bob = -Math.abs(Math.sin(crank * 2)) * 1.0;
    rider.setAttribute('transform', `translate(0 ${bob.toFixed(2)})`);

    // 翅膀扇动 & 围巾飘动
    wing.setAttribute('transform', `rotate(${(Math.sin(t * 3) * 5).toFixed(2)} 298 212)`);
    scarfTail.setAttribute('transform', `rotate(${(Math.sin(t * 7) * 6).toFixed(2)} 340 206)`);

    // 铜铃：自动轻响（可见动画，不发声）
    if (!paused) {
      autoRingTimer -= dt;
      if (autoRingTimer <= 0) {
        ringT = BELL_T;
        autoRingTimer = 5 + rand() * 3;
      }
    }
    if (ringT > 0) ringT = Math.max(0, ringT - dt);
    const k = ringT / BELL_T;
    bellBody.setAttribute('transform',
      `rotate(${(Math.sin((1 - k) * 45) * 22 * k).toFixed(2)} 405 249)`);
    bellArcs.setAttribute('opacity', k.toFixed(2));

    requestAnimationFrame(frame);
  }

  // 初始姿态
  drivePose(0);
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
```

**说明：**
- **背景**：渐变天空、霞光与太阳、随机分布的云层，以及带有太阳倒影的海面。海浪按远近以不同速度流动。
- **自行车**：前后车轮的辐条会随骑行旋转，轮毂为铜色，气门嘴红点可以直观看出转动。踏板和链盘也会跟随运动。
- **鹈鹕**：骑在车座上，腿部使用简单的两段式反向运动（IK）跟随踏板，翅膀会轻轻扇动，围巾随风飘动。
- **铜车铃**：点击铃铛会摇晃并发出提示音（需要浏览器允许音频）；另外每隔几秒会自动轻响。
- **控制**：页面下方的“暂停/继续”按钮可以停止或恢复动画。

```html
<!DOCTYPE html>
<html lang="zh">
<head>
<meta charset="UTF-8">
<title>鹈鹕骑自行车 - 晨雾港口</title>
<style>
  body {
    margin: 0;
