    <title>鹈鹕骑行 - 落日跨海</title>
    <style>
        body {
            margin: 0;
            padding: 0;
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            background-color: #333;
            font-family: sans-serif;
        }

        svg {
            width: 100%;
            height: 100%;
            max-width: 1000px;
            max-height: 600px;
            box-shadow: 0 0 20px rgba(0,0,0,0.5);
        }

        /* 动画定义 */

        /* 1. 整体移动动画 (从右向左，模拟前进) */
        .scene-group {
            animation: rideAcross 12s linear infinite;
        }

        @keyframes rideAcross {
            0% { transform: translateX(900px); }
            100% { transform: translateX(-900px); }
        }

        /* 2. 车轮旋转 */
        .wheel-spin {
            animation: spin 2s linear infinite;
            transform-origin: center;
        }

        @keyframes spin {
            100% { transform: rotate(360deg); }
        }

        /* 3. 鹈鹕身体颠簸 (模拟骑行震动) */
        .pelican-body {
            animation: bounce 0.5s ease-in-out infinite alternate;
            transform-origin: bottom center;
        }

        @keyframes bounce {
            0% { transform: translateY(0); }
            100% { transform: translateY(-3px); }
        }

        /* 4. 翅膀扇动/握把 */
        .wing {
            animation: flap 1s ease-in-out infinite alternate;
            transform-origin: 380px 260px; /* 肩膀位置 */
        }

        @keyframes flap {
            0% { transform: rotate(0deg); }
            100% { transform: rotate(10deg); }
        }

        /* 5. 腿部踩踏 (简化版，随轮子转动) */
        .leg-pedal {
            animation: spin 2s linear infinite;
            transform-origin: 435px 310px; /* 中轴位置 */
        }

        /* 6. 尾迹气泡 */
        .trail-dot {
            opacity: 0;
            animation: trailFade 1.5s linear infinite;
        }
        .trail-dot:nth-child(2) { animation-delay: 0.5s; }
        .trail-dot:nth-child(3) { animation-delay: 1.0s; }

        @keyframes trailFade {
            0% { transform: translate(0, 0) scale(0.5); opacity: 0.8; }
            100% { transform: translate(-60px, -20px) scale(1.5); opacity: 0; }
        }

        /* 7. 太阳下沉微动 */
        .sun {
            animation: sunGlow 4s ease-in-out infinite alternate;
        }
        @keyframes sunGlow {
            0% { filter: drop-shadow(0 0 10px #ffaa00); }
            100% { filter: drop-shadow(0 0 25px #ff5500); }
        }

    </style>
</head>
