(function () {
  const crankCenter = { x: 595, y: 415 };
  const crankRadius = 24;
  const leftHip = { x: 528, y: 360 };
  const rightHip = { x: 542, y: 360 };

  const rearSpokes = document.getElementById('rearSpokes');
  const frontSpokes = document.getElementById('frontSpokes');
  const crank = document.getElementById('crank');
  const legNear = document.getElementById('legNear');
  const legFar = document.getElementById('legFar');
  const pelican = document.getElementById('pelican');
  const wing = document.getElementById('wing');
  const clouds = [
    { el: document.getElementById('cloud1'), base: 120, speed: 14 },
    { el: document.getElementById('cloud2'), base: 520, speed: 10 },
    { el: document.getElementById('cloud3'), base: 860, speed: 18 }
  ];
  const waves = [
    { el: document.getElementById('wave1'), speed: 42 },
    { el: document.getElementById('wave2'), speed: 30 },
    { el: document.getElementById('wave3'), speed: 22 }
  ];

  function solveIK(hip, foot, l1, l2) {
    const dx = foot.x - hip.x;
    const dy = foot.y - hip.y;
    const d = Math.hypot(dx, dy) || 0.001;
    const maxD = l1 + l2;
    const D = d > maxD ? maxD * 0.999 : d;
    const a = (l1 * l1 - l2 * l2 + D * D) / (2 * D);
    const hSq = l1 * l1 - a * a;
    const h = Math.sqrt(Math.max(0, hSq));
    const mx = hip.x + (dx / d) * a;
    const my = hip.y + (dy / d) * a;
    const rx = (-dy / d) * h;
    const ry = (dx / d) * h;
    const k1 = { x: mx + rx, y: my + ry };
    const k2 = { x: mx - rx, y: my - ry };
    return k1.x > k2.x ? k1 : k2;
  }

  function updateLeg(el, hip, foot) {
    const knee = solveIK(hip, foot, 46, 52);
    el.setAttribute('d',
      'M ' + hip.x.toFixed(1) + ' ' + hip.y.toFixed(1) +
      ' L ' + knee.x.toFixed(1) + ' ' + knee.y.toFixed(1) +
      ' L ' + foot.x.toFixed(1) + ' ' + foot.y.toFixed(1)
    );
  }

  let last = null;
  function frame(ts) {
    if (last === null) last = ts;
    const dt = (ts - last) / 1000;
    last = ts;
    const t = ts / 1000;
    const speed = 2.35;
    const angle = t * speed;

    const deg = angle * 180 / Math.PI;
    rearSpokes.setAttribute('transform', 'rotate(' + deg + ' 520 460)');
    frontSpokes.setAttribute('transform', 'rotate(' + deg + ' 690 460)');
    crank.setAttribute('transform', 'rotate(' + deg + ' 595 415)');

    const a0 = angle;
    const a1 = angle + Math.PI;
    const pedal0 = {
      x: crankCenter.x + crankRadius * Math.cos(a0),
      y: crankCenter.y + crankRadius * Math.sin(a0)
    };
    const pedal1 = {
      x: crankCenter.x + crankRadius * Math.cos(a1),
      y: crankCenter.y + crankRadius * Math.sin(a1)
    };

    updateLeg(legNear, leftHip, pedal0);
    updateLeg(legFar, rightHip, pedal1);

    const bob = Math.sin(t * speed * 1.4) * 3.2;
    pelican.setAttribute('transform', 'translate(0 ' + bob.toFixed(2) + ')');

    const wingAngle = Math.sin(t * 6.2) * 13;
    wing.setAttribute('transform', 'rotate(' + wingAngle.toFixed(2) + ' 545 320)');

    clouds.forEach(function (c) {
      const x = (c.base + t * c.speed) % 1320 - 120;
      c.el.setAttribute('transform', 'translate(' + x.toFixed(1) + ',0)');
    });

    waves.forEach(function (w) {
      const x = -(t * w.speed) % 120;
      w.el.setAttribute('transform', 'translate(' + x.toFixed(1) + ',0)');
    });

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);
})();
</script>
