<script>
(() => {
  const NS = 'http://www.w3.org/2000/svg';

  // 固定种子 9888 的伪随机数生成器（mulberry32）
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  const rand = mulberry32(9888);

  const $ = id => document.getElementById(id);
  const el = (tag, attrs = {}, parent) => {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  };
  const setLine = (e, x1, y1, x2, y2) => {
    e.setAttribute('x1', x1); e.setAttribute('y1', y1);
    e.setAttribute('x2', x2); e.setAttribute('y2', y2);
  };

  // ---- 星星 ----
  const starsG = $('stars');
  for (let i = 0; i < 60; i++) {
    el('circle', {
      cx: (rand() * 800).toFixed(1),
      cy: (rand() * 250).toFixed(1),
      r: (0.5 + rand() * 1.2).toFixed(2),
      fill: '#fff',
      class: 'twinkle',
      style: `animation-delay:${(-rand() * 3).toFixed(2)}s`
    }, starsG);
  }

  // ---- 海鸥剪影 ----
  const gullsG = $('gulls');
  const gulls = [];
  for (let i = 0; i < 6; i++) {
    const g = el('g', {}, gullsG);
    const inner = el('g', { class: 'flap', style: `animation-delay:${(-rand()).toFixed(2)}s` }, g);
    el('path', {
      d: 'M-14 0 Q-7 -9 0 -1 Q7 -9 14 0 Q7 -4 0 2 Q-7 -4 -14 0 Z',
      fill: '#1a1030'
    }, inner);
    gulls.push({
      el: g,
      x0: rand() * 900,
      y: 40 + rand() * 150,
      s: 0.8 + rand() * 0.8,
      v: 12 + rand() * 18
    });
  }

  // ---- 海浪（周期 80px，可无缝滚动） ----
  let wd = '';
  for (let y = 326; y <= 380; y += 9) {
    for (let j = 0; j < 2; j++) {
      const x = rand() * 80;
      const w = 10 + rand() * 16;
      for (let k = -2; k <= 11; k++) {
        const xx = x + 80 * k;
        wd += `M${xx.toFixed(1)} ${y} q${(w / 2).toFixed(1)} -3 ${w.toFixed(1)} 0 `;
      }
    }
  }
  const wavesG = $('waves');
  el('path', { d: wd, stroke: '#ffd6b0', 'stroke-opacity': '.25', 'stroke-width': '1.2', fill: 'none' }, wavesG);

  // ---- 路面虚线（周期 80px） ----
  const dashG = $('dash');
  for (let k = -2; k <= 11; k++) {
    el('rect', { x: k * 80, y: 478, width: 40, height: 4, fill: '#f7d774', opacity: '.7' }, dashG);
  }

  // ---- 辐条 ----
  function buildSpokes(g, cx, cy, r) {
    for (let i = 0; i < 16; i++) {
      const a = i * Math.PI / 8;
      el('line', {
        x1: cx, y1: cy,
        x2: (cx + r * Math.cos(a)).toFixed(2),
        y2: (cy + r * Math.sin(a)).toFixed(2),
        stroke: '#c8bcd8', 'stroke-width': '1'
      }, g);
    }
  }
  buildSpokes($('rSp'), 300, 400, 50);
  buildSpokes($('fSp'), 500, 400, 50);

  // ---- 两关节腿部逆运动学（膝盖朝前） ----
  function legIK(hip, foot, L1 = 62, L2 = 70) {
    let dx = foot.x - hip.x, dy = foot.y - hip.y;
    let d = Math.hypot(dx, dy);
    const maxD = L1 + L2 - 1;
    if (d > maxD) { dx *= maxD / d; dy *= maxD / d; d = maxD; }
    const ux = dx / d, uy = dy / d;
    const a = (L1 * L1 - L2 * L2 + d * d) / (2 * d);
    const h = Math.sqrt(Math.max(0, L1 * L1 - a * a));
    const bx = hip.x + a * ux, by = hip.y + a * uy;
    let px = -uy, py = ux;
    if (px < 0) { px = -px; py = -py; }
    return {
      knee: { x: bx + h * px, y: by + h * py },
      foot: { x: hip.x + dx, y: hip.y + dy }
    };
  }

  // ---- 引用元素 ----
  const rSp = $('rSp'), fSp = $('fSp'), ring = $('ring');
  const crA = $('crA'), crB = $('crB'), pdA = $('pdA'), pdB = $('pdB');
  const legA = $('legA'), legB = $('legB');
  const beam = $('beam');
  const hip = { x: 368, y: 290 };
  const BB = { x: 385, y: 400 };
  const CR = 22;

  // ---- 动画循环 ----
  function frame(ts) {
    const t = ts / 1000;

    // 车轮：线速度 90px/s，与路面虚线同步
    const wheelDeg = (t * 90 / 55) * 180 / Math.PI;
    rSp.setAttribute('transform', `rotate(${wheelDeg} 300 400)`);
    fSp.setAttribute('transform', `rotate(${wheelDeg} 500 400)`);

    // 踏板曲柄
    const th = t * 2.2;
    const ca = Math.cos(th), sa = Math.sin(th);
    const A = { x: BB.x + CR * ca, y: BB.y + CR * sa };
    const B = { x: BB.x - CR * ca, y: BB.y - CR * sa };
    ring.setAttribute('transform', `rotate(${th * 180 / Math.PI} 385 400)`);

    setLine(crA, BB.x, BB.y, A.x, A.y);
    setLine(crB, BB.x, BB.y, B.x, B.y);
    setLine(pdA, A.x - 7, A.y, A.x + 7, A.y);
    setLine(pdB, B.x - 7, B.y, B.x + 7, B.y);

    // 腿
    const la = legIK(hip, A);
    const lb = legIK(hip, B);
    legA.setAttribute('d',
      `M${hip.x} ${hip.y} L${la.knee.x.toFixed(2)} ${la.knee.y.toFixed(2)} L${la.foot.x.toFixed(2)} ${la.foot.y.toFixed(2)}`);
    legB.setAttribute('d',
      `M${hip.x} ${hip.y} L${lb.knee.x.toFixed(2)} ${lb.knee.y.toFixed(2)} L${lb.foot.x.toFixed(2)} ${lb.foot.y.toFixed(2)}`);

    // 路面虚线
    dashG.setAttribute('transform', `translate(${-((t * 90) % 80).toFixed(2)} 0)`);

    // 海浪
    wavesG.setAttribute('transform', `translate(${-((t * 18) % 80).toFixed(2)} 0)`);

    // 灯塔光束扫动
    beam.setAttribute('transform', `rotate(${(Math.sin(t * 0.7) * 22).toFixed(2)} 680 189)`);

    // 海鸥飞行
    for (const g of gulls) {
      let x = ((g.x0 - g.v * t) % 900 + 900) % 900 - 50;
      g.el.setAttribute('transform', `translate(${x.toFixed(1)} ${g.y.toFixed(1)}) scale(${g.s.toFixed(2)})`);
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
```

主要效果：
- **场景**：渐变黄昏天空、夕阳与海面倒影、沙滩岩石、带旋转光束的灯塔。
- **鹈鹕**：白色身体、棕色翅膀轻微扇动、红色围巾随风飘动、黄色长喙与喙囊，并戴着带黄铜边框和琥珀色镜片的复古飞行员风镜。
- **骑行**：车轮旋转、踏板与链盘转动，双腿通过逆运动学跟随踏板；路面虚线和海浪以相同速度滚动，营造前进感。
- **随机性**：星星、海鸥位置和海浪形状由种子 9888 生成，结果可复现。

