  const cloudData = [
    {x: 120, y: 60, s: 0.4},
    {x: 400, y: 90, s: 0.25},
    {x: 680, y: 50, s: 0.35}
  ];
  const clouds = cloudData.map((c, i) => {
    const g = document.createElementNS('http://www.w3.org/2000/svg', 'g');
    g.setAttribute('transform', `translate(${c.x},${c.y})`);
    const e1 = document.createElementNS('http://www.w3.org/2000/svg', 'ellipse');
    e1.setAttribute('cx', 0); e1.setAttribute('cy', 0); e1.setAttribute('rx', 40); e1.setAttribute('ry', 18); e1.setAttribute('fill', '#fff');
    const e2 = document.createElementNS('http://www.w3.org/2000/svg', 'ellipse');
    e2.setAttribute('cx', 30); e2.setAttribute('cy', -5); e2.setAttribute('rx', 30); e2.setAttribute('ry', 15); e2.setAttribute('fill', '#fff');
    const e3 = document.createElementNS('http://www.w3.org/2000/svg', 'ellipse');
    e3.setAttribute('cx', -25); e3.setAttribute('cy', 5); e3.setAttribute('rx', 25); e3.setAttribute('ry', 12); e3.setAttribute('fill', '#fff');
    g.appendChild(e1); g.appendChild(e2); g.appendChild(e3);
    cloudsLayer.appendChild(g);
    return {el: g, baseX: c.x, y: c.y, speed: c.s};
  });

  // 生成波浪路径
  function makeWavePath(yOffset, color, opacity) {
    let d = `M0,${yOffset}`;
    const period = 40;
    const count = 24;
    for (let i = 0; i < count; i++) {
      const x = i * period;
      d += ` Q${x+10},${yOffset-6} ${x+20},${yOffset} Q${x+30},${yOffset+6} ${x+40},${yOffset}`;
    }
    const p = document.createElementNS('http://www.w3.org/2000/svg', 'path');
    p.setAttribute('d', d);
    p.setAttribute('fill', 'none');
    p.setAttribute('stroke', color);
    p.setAttribute('stroke-width', '2');
    p.setAttribute('opacity', opacity);
    return p;
  }
  wavesLayer.appendChild(makeWavePath(10, '#aee3ff', 0.7));
  wavesLayer.appendChild(makeWavePath(22, '#7fc8ff', 0.5));

  // 生成木板
  for (let i = 0; i < 26; i++) {
    const r = document.createElementNS('http://www.w3.org/2000/svg', 'rect');
    r.setAttribute('x', i * 40);
    r.setAttribute('y', 0);
    r.setAttribute('width', 3);
    r.setAttribute('height', 60);
    r.setAttribute('fill', '#6b4226');
    planksLayer.appendChild(r);
  }

  // 元素引用
  const rearWheel = document.getElementById('rearWheel');
  const frontWheel = document.getElementById('frontWheel');
  const pedalLeft = document.getElementById('pedalLeft');
  const pedalRight = document.getElementById('pedalRight');
  const armLeft = document.getElementById('armLeft');
  const armRight = document.getElementById('armRight');
  const pelican = document.getElementById('pelican');
  const headGroup = document.getElementById('headGroup');
  const legLeft = document.getElementById('legLeft');
  const legRight = document.getElementById('legRight');

  let t = 0;
  function animate() {
    t += 0.05;
    const deg = (t * 2) * 180 / Math.PI;

    // 车轮旋转
    rearWheel.setAttribute('transform', `rotate(${deg})`);
    frontWheel.setAttribute('transform', `translate(120,0) rotate(${deg})`);

    // 踏板位置
    const theta = t * 2;
    const r = 22;
    const cx = 50, cy = -30;
    const leftX = cx + r * Math.cos(theta);
    const leftY = cy + r * Math.sin(theta);
    const rightX = cx + r * Math.cos(theta + Math.PI);
    const rightY = cy + r * Math.sin(theta + Math.PI);

    pedalLeft.setAttribute('transform', `translate(${leftX},${leftY})`);
    pedalRight.setAttribute('transform', `translate(${rightX},${rightY})`);

    armLeft.setAttribute('x2', leftX);
    armLeft.setAttribute('y2', leftY);
    armRight.setAttribute('x2', rightX);
    armRight.setAttribute('y2', rightY);

    // 鹈鹕上下浮动
    const bob = Math.sin(t * 2) * 3;
    pelican.setAttribute('transform', `translate(25,${-100 + bob})`);

    // 头部轻微转动
    headGroup.setAttribute('transform', `rotate(${Math.sin(t) * 3}, 35, -25)`);

    // 腿跟随踏板
    const pelX = 25, pelY = -100 + bob;
    const hipL = {x: 15, y: 20};
    const hipR = {x: 35, y: 20};
    const pL = {x: leftX - pelX, y: leftY - pelY};
    const pR = {x: rightX - pelX, y: rightY - pelY};

    legLeft.setAttribute('x1', hipL.x);
    legLeft.setAttribute('y1', hipL.y);
    legLeft.setAttribute('x2', pL.x);
    legLeft.setAttribute('y2', pL.y);

    legRight.setAttribute('x1', hipR.x);
    legRight.setAttribute('y1', hipR.y);
    legRight.setAttribute('x2', pR.x);
    legRight.setAttribute('y2', pR.y);

    // 步道滚动
    const bwOffset = (t * 40) % 40;
    planksLayer.setAttribute('transform', `translate(${-bwOffset},0)`);

    // 波浪滚动
    const waveOffset = (t * 20) % 40;
    wavesLayer.setAttribute('transform', `translate(${-waveOffset},260)`);

    // 云移动
    clouds.forEach(c => {
      let x = (c.baseX + t * c.speed * 60) % 980;
      if (x > 900) x -= 980;
      c.el.setAttribute('transform', `translate(${x},${c.y})`);
    });

    requestAnimationFrame(animate);
  }
  animate();
</script>
</body>
