<!DOCTYPE html>
<!-- 
  训练标记：#PB-mvb11bvf-2193cc34
  随机种子：2014
  场景细节：珊瑚礁浅滩碧波背景，鹈鹕背着迷你邮差包轻快骑行
-->
<html lang="zh-CN">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>鹈鹕信使的浅滩骑行 | Pelican's Lagoon Ride</title>
  <style>
    * {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    body {
      background: #022b3a;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }

    .canvas-container {
      width: 100vw;
      height: 100vh;
      max-width: 1400px;
      max-height: 900px;
      position: relative;
      box-shadow: 0 25px 60px rgba(0, 0, 0, 0.4);
      display: flex;
      align-items: center;
      justify-content: center;
      background: #104f55;
    }

    svg {
      width: 100%;
      height: 100%;
      display: block;
      overflow: hidden;
    }

    /* =================== 动画定义 =================== */
    /* 车轮持续滚动 */
    .wheel-spin {
      transform-origin: center;
      animation: wheelRotate 1.2s linear infinite;
    }
    @keyframes wheelRotate {
      from { transform: rotate(0deg); }
      to { transform: rotate(360deg); }
    }

    /* 骑行整体轻快起伏（颠簸与韵律感） */
    .pelican-rider {
      animation: breezyRide 0.6s ease-in-out infinite alternate;
    }
    @keyframes breezyRide {
      0% { transform: translateY(0px) rotate(0deg); }
      100% { transform: translateY(-7px) rotate(-1deg); }
    }

    /* 脚踏板与曲柄联动 */
    .pedal-system {
      transform-origin: 590px 560px;
      animation: wheelRotate 1.2s linear infinite;
    }

    /* 邮差包轻盈回弹（次级运动） */
    .messenger-bag {
      transform-origin: 520px 410px;
      animation: bagSwing 0.6s ease-in-out infinite alternate;
    }
    @keyframes bagSwing {
      0% { transform: rotate(-3deg) translateY(0); }
      100% { transform: rotate(6deg) translateY(-4px); }
    }

    /* 大喉囊与嘴部呼吸抖动 */
    .throat-pouch {
      transform-origin: 670px 270px;
      animation: pouchWobble 1.2s ease-in-out infinite;
    }
    @keyframes pouchWobble {
      0%, 100% { transform: scale(1, 1); }
      50% { transform: scale(1.04, 0.96) translateY(2px); }
    }

    /* 碧波浪花层向左缓缓流动 */
    .wave-flow-slow {
      animation: waveDrift 8s linear infinite;
    }
    .wave-flow-fast {
      animation: waveDrift 4.5s linear infinite;
    }
    @keyframes waveDrift {
      0% { transform: translateX(0); }
      100% { transform: translateX(-400px); }
    }

    /* 珊瑚与海葵在浅滩水流中摇曳 */
    .coral-sway-1 {
      transform-origin: bottom center;
      animation: coralSway 3s ease-in-out infinite alternate;
    }
    .coral-sway-2 {
      transform-origin: bottom center;
      animation: coralSway 2.3s ease-in-out infinite alternate-reverse;
    }
    @keyframes coralSway {
      0% { transform: rotate(-5deg); }
      100% { transform: rotate(6deg); }
    }

    /* 浅滩水光潋滟（焦散反光） */
    .caustics {
      animation: causticFlicker 3s ease-in-out infinite alternate;
    }
    @keyframes causticFlicker {
      0% { opacity: 0.25; transform: scale(0.98); }
      100% { opacity: 0.55; transform: scale(1.02); }
    }

    /* 游动的热带小鱼 */
    .reef-fish-1 {
      animation: fishSwim1 14s linear infinite;
    }
    .reef-fish-2 {
      animation: fishSwim2 18s linear infinite 3s;
    }
    @keyframes fishSwim1 {
      0% { transform: translate(1250px, 0); }
      100% { transform: translate(-200px, 15px); }
    }
    @keyframes fishSwim2 {
      0% { transform: translate(1250px, -20px) scale(0.85); }
      100% { transform: translate(-200px, -5px) scale(0.85); }
    }

    /* 水底气泡徐徐上升 */
    .bubble {
      animation: bubbleRise 4s ease-in infinite;
    }
    @keyframes bubbleRise {
      0% { transform: translateY(0) scale(0.7); opacity: 0; }
      20% { opacity: 0.8; }
      80% { opacity: 0.8; }
      100% { transform: translateY(-160px) scale(1.2); opacity: 0; }
    }

    /* 邮差帽小羽毛/飘带随风飘扬 */
    .cap-feather {
      transform-origin: 640px 190px;
      animation: featherFlutter 0.4s ease-in-out infinite alternate;
    }
    @keyframes featherFlutter {
      0% { transform: rotate(-8deg); }
      100% { transform: rotate(12deg); }
    }

    /* 右侧腿部踩踏连杆模拟 */
    .front-leg {
      transform-origin: 555px 430px;
      animation: legMotion 1.2s ease-in-out infinite;
    }
    @keyframes legMotion {
      0% { transform: rotate(-15deg); }
      25% { transform: rotate(15deg); }
      50% { transform: rotate(30deg); }
      75% { transform: rotate(5deg); }
      100% { transform: rotate(-15deg); }
    }
  </style>
</head>
