    <path d="M58,-86 Q50,-90 44,-92" stroke="#bdbdbd" stroke-width="4" fill="none" stroke-linecap="round"/>
    <line x1="45" y1="-92" x2="36" y2="-93" stroke="#333" stroke-width="6" stroke-linecap="round"/>
    <circle cx="54" cy="-93" r="3.2" fill="#ffd34d" stroke="#c9a12a" stroke-width="1"/>
    <path d="M70,-52 l9,-2 l0,7 l-9,-1 Z" fill="#fff6c0" stroke="#bbb" stroke-width="1"/>

    <!-- 近侧曲柄与腿 -->
    <line id="nearCrank" stroke="#8a8a8a" stroke-width="4" stroke-linecap="round"/>
    <rect id="nearPedal" x="-7" y="-2" width="14" height="4" rx="1.5" fill="#444"/>
    <path id="nearLeg" fill="none" stroke="#f39c1f" stroke-width="7.5" stroke-linecap="round" stroke-linejoin="round"/>
    <g id="nearFoot">
      <path d="M-6,-3 L14,-5 L17,0 L13,3 L-5,3 Z" fill="#ec8d12"/>
      <path d="M0,-3 L14,-1 M1,1 L13,2" stroke="#c4700f" stroke-width="0.8"/>
    </g>

    <!-- 鹈鹕 -->
    <g id="pelican">
      <!-- 尾巴 -->
      <path d="M-92,-108 L-114,-101 L-110,-94 L-89,-96 Z" fill="#f4f7f8" stroke="#b8c4ca" stroke-width="1.5"/>
      <path d="M-104,-103 L-113,-100 L-110,-96 Z" fill="#59656e"/>
      <!-- 脖子描边（身体后面） -->
      <path d="M2,-142 C-14,-172 42,-178 30,-206" fill="none" stroke="#b8c4ca" stroke-width="25" stroke-linecap="round"/>
      <!-- 身体 -->
      <path d="M-95,-112 C-82,-152 -25,-168 10,-152 C35,-142 38,-110 18,-94 C-5,-78 -55,-78 -80,-92 Z"
            fill="#fbfcfc" stroke="#b8c4ca" stroke-width="2"/>
      <path d="M-70,-90 C-50,-82 -10,-82 12,-96" fill="none" stroke="#e1e8eb" stroke-width="5" stroke-linecap="round"/>
      <!-- 脖子 -->
      <path d="M2,-142 C-14,-172 42,-178 30,-206" fill="none" stroke="#fbfcfc" stroke-width="21" stroke-linecap="round"/>
      <path d="M-4,-160 C-2,-172 20,-176 26,-190" fill="none" stroke="#f3ead0" stroke-width="5" stroke-linecap="round" opacity="0.7"/>
      <!-- 邮差包背带 -->
      <path d="M12,-152 C2,-128 -22,-110 -46,-103" fill="none" stroke="#7a4a24" stroke-width="4.5" stroke-linecap="round"/>
      <path d="M12,-152 C2,-128 -22,-110 -46,-103" fill="none" stroke="#a8693a" stroke-width="1.2" stroke-dasharray="3 3"/>
      <!-- 翅膀 -->
      <path d="M-60,-140 C-30,-156 5,-152 18,-132 C26,-120 36,-104 46,-92 L40,-87 C28,-96 14,-104 -4,-108 C-28,-112 -50,-118 -64,-128 Z"
            fill="#e3e9ec" stroke="#9fadb5" stroke-width="1.5"/>
      <path d="M-44,-136 q8,6 18,4 M-30,-128 q8,6 18,4 M-16,-122 q7,6 16,4 M-48,-124 q8,5 18,3" fill="none" stroke="#b3c0c7" stroke-width="1.3"/>
      <path d="M14,-122 C24,-110 36,-98 46,-92 L40,-87 C30,-95 18,-104 6,-110 Z" fill="#2f3a44"/>
      <path d="M38,-95 q6,-1 8,3 q-3,4 -8,2 Z" fill="#2f3a44"/>
      <!-- 邮差包 -->
      <g id="bag">
        <g transform="rotate(-12 -58 -106)">
          <rect x="-66" y="-113" width="17" height="11" fill="#fffdf5" stroke="#c9b48a" stroke-width="1"/>
          <path d="M-66,-113 l8.5,6 l8.5,-6" fill="none" stroke="#e05a4f" stroke-width="1.2"/>
        </g>
        <rect x="-78" y="-104" width="38" height="28" rx="5" fill="#2f5d9e" stroke="#1d3f70" stroke-width="1.5"/>
        <path d="M-78,-99 Q-78,-104 -73,-104 L-45,-104 Q-40,-104 -40,-99 L-40,-90 Q-59,-84 -78,-90 Z" fill="#244b84"/>
        <path d="M-78,-96 L-40,-96" stroke="#ffd34d" stroke-width="2.5"/>
        <rect x="-62.5" y="-91" width="7" height="6" rx="1" fill="#ffd34d" stroke="#b8922a" stroke-width="0.8"/>
        <g transform="translate(-71,-84)">
          <rect x="0" y="0" width="8" height="5.5" fill="none" stroke="#ffd34d" stroke-width="0.9"/>
          <path d="M0,0 l4,3 l4,-3" fill="none" stroke="#ffd34d" stroke-width="0.9"/>
        </g>
      </g>
      <!-- 头部 -->
      <g id="head">
        <path d="M20,-221 C10,-230 2,-228 0,-224 C8,-224 13,-220 18,-216 Z" fill="#f2df95"/>
        <path d="M22,-225 C14,-236 6,-236 3,-233 C11,-231 16,-227 20,-221 Z" fill="#f6e7a8"/>
        <ellipse cx="35" cy="-212" rx="19" ry="16" fill="#fffaf0" stroke="#b8c4ca" stroke-width="2"/>
        <ellipse cx="39" cy="-215" rx="8" ry="6.5" fill="#f9d3c2"/>
        <g id="pouch">
          <path d="M48,-206 C78,-206 112,-203 139,-200 C122,-182 90,-170 66,-177 C52,-182 46,-194 48,-206 Z"
                fill="#f59d7e" stroke="#d97b5c" stroke-width="1.5"/>
          <path d="M60,-192 C80,-186 105,-188 125,-196" fill="none" stroke="#e5876a" stroke-width="1"/>
        </g>
        <path d="M46,-220 C80,-215 118,-209 142,-205 Q154,-203 148,-195 Q146,-200 139,-200 C112,-203 78,-206 48,-206 Z"
              fill="#f7b733" stroke="#c98a1a" stroke-width="1.5"/>
        <path d="M52,-213 C85,-209 115,-205 139,-202" stroke="#d9951f" stroke-width="1.2" fill="none"/>
        <circle cx="38" cy="-216" r="5" fill="#fff4c2" stroke="#e0b84a" stroke-width="1"/>
        <g id="pupil">
          <circle cx="38.6" cy="-216" r="2.5" fill="#1a1a1a"/>
          <circle cx="39.4" cy="-217" r="0.85" fill="#fff"/>
        </g>
      </g>
    </g>
  </g>
</svg>
<div class="caption">🐦 鹈鹕邮差 · 珊瑚礁浅滩的清晨派送</div>
</div>

<script>
(function () {
  const NS = "http://www.w3.org/2000/svg";
  const W = 960;
  const $ = id => document.getElementById(id);
  function el(tag, attrs, parent) {
    const e = document.createElementNS(NS, tag);
    for (const k in attrs) e.setAttribute(k, attrs[k]);
    if (parent) parent.appendChild(e);
    return e;
  }

  // 随机种子 2014
  function mulberry32(a) {
    return function () {
      a |= 0; a = a + 0x6D2B79F5 | 0;
      let t = Math.imul(a ^ a >>> 15, 1 | a);
      t = t + Math.imul(t ^ t >>> 7, 61 | t) ^ t;
      return ((t ^ t >>> 14) >>> 0) / 4294967296;
    };
  }
  const rand = mulberry32(2014);
  const rnd = (a, b) => a + (b - a) * rand();
  const pick = arr => arr[Math.floor(rand() * arr.length)];

  function shade(hex, p) {
    const n = parseInt(hex.slice(1), 16);
    const f = v => Math.max(0, Math.min(255, Math.round(p < 0 ? v * (1 + p) : v + (255 - v) * p)));
    return `rgb(${f(n >> 16)},${f(n >> 8 & 255)},${f(n & 255)})`;
  }

  // 可无缝循环的图层：生成一块宽 W 的瓦片并复制三份
  const layers = [];
  function makeLayer(parentId, factor, builder) {
    const parent = $(parentId);
    const wrap = el("g", {}, parent);
    const tile = el("g", {}, null);
    builder(tile);
    [-W, 0, W].forEach(off => {
      const c = tile.cloneNode(true);
      c.setAttribute("transform", `translate(${off},0)`);
      wrap.appendChild(c);
    });
    layers.push({ g: wrap, f: factor });
    return wrap;
  }

  // ---------- 云 ----------
  makeLayer("clouds", 0.05, g => {
    for (let i = 0; i < 4; i++) {
      const cx = i * 240 + rnd(20, 160), cy = rnd(35, 130), s = rnd(0.7, 1.2);
      const c = el("g", { opacity: 0.92 }, g);
      [[0, 0, 34, 16], [-28, 6, 24, 12], [28, 5, 26, 13], [8, -12, 22, 14]].forEach(e => {
        el("ellipse", { cx: cx + e[0] * s, cy: cy + e[1] * s, rx: e[2] * s, ry: e[3] * s, fill: "#ffffff" }, c);
      });
      el("ellipse", { cx: cx, cy: cy + 10 * s, rx: 50 * s, ry: 6 * s, fill: "#e3f4fb" }, c);
    }
  });

  // ---------- 远处小岛 ----------
  makeLayer("island", 0.02, g => {
    function islet(x, s) {
      el("path", { d: `M${x - 80 * s},201 Q${x},${201 - 22 * s} ${x + 80 * s},201 Z`, fill: "#3f9c6d" }, g);
      el("path", { d: `M${x - 85 * s},202 Q${x},${197 - 6 * s} ${x + 85 * s},202 Z`, fill: "#f2e0b0" }, g);
      for (let k = 0; k < 2; k++) {
        const px = x + (k ? 18 : -14) * s, top = 201 - (k ? 44 : 52) * s;
        el("path", { d: `M${px},${198 - 10 * s} Q${px + 6 * s},${(198 + top) / 2} ${px + 3 * s},${top}`, stroke: "#7b5a3a", "stroke-width": 2.5 * s, fill: "none" }, g);
        for (let a = 0; a < 5; a++) {
          const ang = -Math.PI + a * Math.PI / 4;
          const ex = px + 3 * s + Math.cos(ang) * 16 * s, ey = top + Math.sin(ang) * 8 * s + 6 * s;
          el("path", { d: `M${px + 3 * s},${top} Q${(px + 3 * s + ex) / 2},${top - 6 * s} ${ex},${ey}`, stroke: "#2f8a55", "stroke-width": 3 * s, fill: "none", "stroke-linecap": "round" }, g);
        }
      }
    }
    islet(170, 0.8);
    islet(620, 0.55);
  });

  // ---------- 阳光粼光 ----------
  (function () {
    const g = $("glints");
    for (let i = 0; i < 26; i++) {
      const nearSun = i < 16;
      const x = nearSun ? 820 + rnd(-45, 45) : rnd(20, 940);
      const y = nearSun ? rnd(205, 265) : rnd(206, 250);
      const s = rnd(2, 5);
      const p = el("path", { d: `M${x - s},${y} L${x},${y - s * 0.35} L${x + s},${y} L${x},${y + s * 0.35} Z`, fill: "#ffffff", opacity: 0 }, g);
      const d = rnd(1.2, 2.8);
      el("animate", { attributeName: "opacity", values: "0;0.95;0", dur: d.toFixed(2) + "s", begin: (-rand() * d).toFixed(2) + "s", repeatCount: "indefinite" }, p);
    }
  })();

  // ---------- 珊瑚构件 ----------
  const coralColors = ["#ff7b7b", "#ff9f5a", "#ffcf5c", "#c77dff", "#ff6fa8", "#ff8a65", "#f78fb3", "#7be0ff"];

  function branchCoral(g, x, y, s, c) {
    const grp = el("g", {}, g);
    const tip = shade(c, 0.35);
    function br(x1, y1, ang, len, w, depth) {
      const x2 = x1 + Math.cos(ang) * len, y2 = y1 + Math.sin(ang) * len;
      el("line", { x1, y1, x2, y2, stroke: c, "stroke-width": w, "stroke-linecap": "round" }, grp);
      if (depth > 0) {
        br(x2, y2, ang - rnd(0.25, 0.6), len * rnd(0.65, 0.82), w * 0.75, depth - 1);
        br(x2, y2, ang + rnd(0.25, 0.6), len * rnd(0.65, 0.82), w * 0.75, depth - 1);
      } else {
        el("circle", { cx: x2, cy: y2, r: w * 0.6, fill: tip }, grp);
      }
    }
    br(x, y, -Math.PI / 2 + rnd(-0.2, 0.2), 28 * s, 8 * s, 3);
  }

  function fanCoral(g, x, y, s, c) {
    const r = 42 * s, a1 = -150 * Math.PI / 180, a2 = -30 * Math.PI / 180;
    el("path", {
      d: `M${x},${y} L${x + r * Math.cos(a1)},${y + r * Math.sin(a1)} A${r} ${r} 0 0 1 ${x + r * Math.cos(a2)},${y + r * Math.sin(a2)} Z`,
      fill: c, opacity: 0.5
    }, g);
    const dark = shade(c, -0.25);
    for (let i = 0; i <= 8; i++) {
      const a = a1 + (a2 - a1) * i / 8;
      el("line", { x1: x, y1: y, x2: x + Math.cos(a) * r * 0.97, y2: y + Math.sin(a) * r * 0.97, stroke: dark, "stroke-width": 1.4 * s }, g);
    }
    [0.45, 0.7, 0.92].forEach(k => {
      const rr = r * k;
      el("path", { d: `M${x + rr * Math.cos(a1)},${y + rr * Math.sin(a1)} A${rr} ${rr} 0 0 1 ${x + rr * Math.cos(a2)},${y + rr * Math.sin(a2)}`, fill: "none", stroke: dark, "stroke-width": 1 * s }, g);
    });
    el("line", { x1: x, y1: y, x2: x, y2: y - 6 * s, stroke: dark, "stroke-width": 3 * s, "stroke-linecap": "round" }, g);
  }

  function brainCoral(g, x, y, s, c) {
    const r = 26 * s;
    el("path", { d: `M${x - r},${y} A${r} ${r * 0.75} 0 0 1 ${x + r},${y} Z`, fill: c }, g);
    const dark = shade(c, -0.28);
    for (let i = 0; i < 4; i++) {
      const yy = y - r * 0.12 - i * r * 0.15, w = r * (0.88 - i * 0.2), n = 6;
      let d = `M${x - w},${yy}`;
      for (let k = 1; k <= n; k++) {
        d += ` Q${x - w + (2 * w / n) * (k - 0.5)},${yy + (k % 2 ? -4 : 4) * s} ${x - w + (2 * w / n) * k},${yy}`;
      }
      el("path", { d, fill: "none", stroke: dark, "stroke-width": 1.5 * s }, g);
    }
  }

  function tubeCoral(g, x, y, s, c) {
    const n = 3 + Math.floor(rand() * 3);
    for (let i = 0; i < n; i++) {
      const h = rnd(20, 46) * s, w = 8 * s, xx = x + (i - n / 2) * w * 1.25;
      el("rect", { x: xx, y: y - h, width: w, height: h, rx: w / 2, fill: i % 2 ? c : shade(c, 0.18) }, g);
      el("ellipse", { cx: xx + w / 2, cy: y - h + w * 0.42, rx: w * 0.33, ry: w * 0.2, fill: shade(c, -0.45) }, g);
    }
  }

  function seaweed(g, x, y, s) {
    const h = rnd(40, 75) * s;
    const p = el("path", {
      d: `M${x},${y} C${x - 10 * s},${y - h * 0.3} ${x + 10 * s},${y - h * 0.6} ${x - 3 * s},${y - h}`,
      fill: "none", stroke: pick(["#2fa36b", "#3dbb7a", "#5cc58a"]), "stroke-width": 4 * s, "stroke-linecap": "round"
    }, g);
    el("animateTransform", {
      attributeName: "transform", type: "rotate",
      values: `-6 ${x} ${y};6 ${x} ${y};-6 ${x} ${y}`, dur: rnd(2.5, 4).toFixed(2) + "s", repeatCount: "indefinite"
    }, p);
  }

  function rock(g, x, y, s) {
    el("ellipse", { cx: x, cy: y, rx: rnd(14, 26) * s, ry: rnd(7, 12) * s, fill: pick(["#5f8f9a", "#6b9aa3", "#4f7f8c"]) }, g);
  }

  function bubble(g, x, y) {
    const c = el("circle", { cx: x, cy: y, r: rnd(1.5, 3.5).toFixed(2), fill: "none", stroke: "#effffe", "stroke-width": 1, opacity: 0 }, g);
    const d = rnd(2.5, 5), b = (-rand() * d).toFixed(2) + "s";
    el("animate", { attributeName: "cy", values: `${y};${y - rnd(60, 110)}`, dur: d.toFixed(2) + "s", begin: b, repeatCount: "indefinite" }, c);
    el("animate", { attributeName: "opacity", values: "0;0.9;0", dur: d.toFixed(2) + "s", begin: b, repeatCount: "indefinite" }, c);
  }

  function randomCoral(g, x, y, s) {
    const c = pick(coralColors);
    const t = rand();
    if (t < 0.3) branchCoral(g, x, y, s, c);
    else if (t < 0.5) fanCoral(g, x, y, s, c);
    else if (t < 0.75) brainCoral(g, x, y, s, c);
    else tubeCoral(g, x, y, s, c);
  }

  // 远景珊瑚
  makeLayer("farCoral", 0.18, g => {
    for (let i = 0; i < 16; i++) {
      const x = i * (W / 16) + rnd(0, 40), y = rnd(285, 335), s = rnd(0.35, 0.6);
      if (rand() < 0.3) rock(g, x, y, s);
      randomCoral(g, x, y, s);
    }
  });

  // 近景珊瑚
  makeLayer("nearCoral", 0.38, g => {
    for (let i = 0; i < 11; i++) {
      const x = i * (W / 11) + rnd(0, 50), y = rnd(395, 432), s = rnd(0.75, 1.2);
      if (rand() < 0.5) rock(g, x + rnd(-20, 20), y + 2, s);
      randomCoral(g, x, y, s);
      if (rand() < 0.6) seaweed(g, x + rnd(25, 45), y, rnd(0.7, 1.1));
      for (let b = 0; b < 3; b++) bubble(g, x + rnd(-10, 10), y - rnd(20, 40));
    }
    // 浅水焦散光纹
    for (let i = 0; i < 14; i++) {
      const x = rnd(0, W), y = rnd(360, 425), w = rnd(18, 40);
      const p = el("path", { d: `M${x},${y} q${w / 2},-5 ${w},0 q${w / 2},5 ${w},0`, fill: "none", stroke: "#e8fffb", "stroke-width": 1.6, opacity: 0 }, g);
      const d = rnd(2, 4);
      el("animate", { attributeName: "opacity", values: "0;0.6;0", dur: d.toFixed(2) + "s", begin: (-rand() * d).toFixed(2) + "s", repeatCount: "indefinite" }, p);
    }
  });

  // 波纹（多层视差）
  [[212, 0.04, 0.6, 0.45], [228, 0.08, 0.8, 0.45], [250, 0.13, 1.0, 0.42], [278, 0.2, 1.2, 0.4],
   [312, 0.28, 1.4, 0.35], [350, 0.38, 1.6, 0.32], [392, 0.5, 1.8, 0.3]].forEach(row => {
    const [y, f, s, op] = row;
    makeLayer("waves", f, g => {
      const n = Math.round(14 / s);
      for (let i = 0; i < n; i++) {
        const x = i * (W / n) + rnd(0, W / n * 0.6), yy = y + rnd(-4, 4), k = 7 * s * rnd(0.8, 1.3);
        el("path", {
          d: `M${x},${yy} q${k},${-k * 0.5} ${2 * k},0 q${k},${-k * 0.5} ${2 * k},0`,
          fill: "none", stroke: "#ffffff", "stroke-width": (1 + s * 0.5).toFixed(2), "stroke-linecap": "round", opacity: op
        }, g);
      }
    });
  });

  // ---------- 鱼 ----------
  const fishes = [];
  (function () {
    const g = $("fish");
    const palettes = [["#ffd23f", "#2b7bd6"], ["#ff8c42", "#ffffff"], ["#5ad1ff", "#1d4e89"], ["#ff6fa8", "#ffe066"]];
    for (let i = 0; i < 7; i++) {
      const [c1, c2] = pick(palettes);
      const fg = el("g", {}, g);
      const tail = el("path", { d: "M-8,0 L-17,-6 L-15,0 L-17,6 Z", fill: c1 }, fg);
      el("ellipse", { cx: 0, cy: 0, rx: 10, ry: 5.5, fill: c1 }, fg);
      el("path", { d: "M-2,-5 Q0,0 -2,5", stroke: c2, "stroke-width": 2, fill: "none" }, fg);
      el("circle", { cx: 5.5, cy: -1.5, r: 1.3, fill: "#1a1a1a" }, fg);
      fishes.push({
        g: fg, tail, x: rnd(0, W), y: rnd(300, 420), dir: rand() < 0.5 ? -1 : 1,
        sp: rnd(18, 45), s: rnd(0.6, 1.1), ph: rand() * 6
      });
    }
  })();

  // ---------- 岸边浪花 ----------
  const SHORE_P = 90;
  const shoreG = (function () {
    const g = el("g", {}, $("shore"));
    function wave(x0, x1, y, a, P) {
      let d = `M${x0},${y} Q${x0 + P / 4},${y - a} ${x0 + P / 2},${y}`;
      let x = x0 + P;
      for (; x <= x1 + P; x += P / 2) d += ` T${x},${y}`;
      return { d, end: x - P / 2 };
    }
    const w1 = wave(-2 * SHORE_P, W + 2 * SHORE_P, 436, 3.5, SHORE_P);
    el("path", { d: w1.d + ` L${w1.end},452 L${-2 * SHORE_P},452 Z`, fill: "#cfb381", opacity: 0.85 }, g);
    const w2 = wave(-2 * SHORE_P, W + 2 * SHORE_P, 430, 2.5, SHORE_P);
    el("path", { d: w2.d, fill: "none", stroke: "#ffffff", "stroke-width": 1.5, opacity: 0.55 }, g);
    el("path", { d: w1.d, fill: "none", stroke: "#ffffff", "stroke-width": 3.5, opacity: 0.95, "stroke-linecap": "round" }, g);
    const w3 = wave(-2 * SHORE_P, W + 2 * SHORE_P, 440, 2, SHORE_P / 2);
    el("path", { d: w3.d, fill: "none", stroke: "#ffffff", "stroke-width": 1.2, opacity: 0.4, "stroke-dasharray": "6 10" }, g);
    return g;
  })();

  // ---------- 沙滩装饰 ----------
  makeLayer("sandDeco", 1.0, g => {
    for (let i = 0; i < 30; i++) {
      const x = rnd(0, W), y = rnd(462, 535), w = rnd(14, 30);
      el("path", { d: `M${x},${y} q${w / 2},-4 ${w},0`, fill: "none", stroke: "#dcbf88", "stroke-width": 1.5, "stroke-linecap": "round" }, g);
    }
    for (let i = 0; i < 22; i++) {
      el("ellipse", { cx: rnd(0, W), cy: rnd(448, 535), rx: rnd(1.5, 3.5), ry: rnd(1, 2.2), fill: pick(["#c9ad7a", "#b8a07a", "#e8d3a8", "#a89070"]) }, g);
    }
    for (let i = 0; i < 6; i++) {
      const x = rnd(20, W - 20), y = rnd(465, 530), s = rnd(0.7, 1.2), c = pick(["#ffe2d1", "#ffd1dc", "#fff1c9"]);
      const sg = el("g", { transform: `translate(${x},${y}) scale(${s}) rotate(${rnd(-30, 30)})` }, g);
      el("path", { d: "M0,4 L-7,-3 A8 8 0 0 1 7,-3 Z", fill: c, stroke: "#d9a98e", "stroke-width": 0.8 }, sg);
      el("path", { d: "M0,4 L-3,-6 M0,4 L0,-7 M0,4 L3,-6", stroke: "#d9a98e", "stroke-width": 0.7 }, sg);
    }
    for (let i = 0; i < 3; i++) {
      const x = rnd(40, W - 40), y = rnd(475, 528), R = rnd(7, 10), r = R * 0.42, rot = rnd(0, 72);
      let pts = [];
      for (let k = 0; k < 10; k++) {
        const a = (rot + k * 36 - 90) * Math.PI / 180, rr = k % 2 ? r : R;
        pts.push((x + Math.cos(a) * rr).toFixed(1) + "," + (y + Math.sin(a) * rr).toFixed(1));
      }
      el("polygon", { points: pts.join(" "), fill: pick(["#ff8a65", "#ff6f61", "#ffa94d"]), stroke: "#d9583f", "stroke-width": 0.8, "stroke-linejoin": "round" }, g);
    }
  });

  // ---------- 车轮辐条 ----------
  function buildSpokes(id) {
    const g = $(id);
    el("circle", { r: 55, fill: "none", stroke: "#474747", "stroke-width": 3, "stroke-dasharray": "3 5" }, g);
    for (let i = 0; i < 16; i++) {
      const a = i / 16 * Math.PI * 2;
      el("line", { x1: Math.cos(a) * 5, y1: Math.sin(a) * 5, x2: Math.cos(a) * 48, y2: Math.sin(a) * 48, stroke: "#cfd8dc", "stroke-width": 1.2 }, g);
    }
    el("rect", { x: -2, y: -49, width: 4, height: 6, fill: "#ff6b57" }, g);
  }
  buildSpokes("rearSpokes");
  buildSpokes("frontSpokes");

  // ---------- 动画 ----------
  const SPEED = 170, R = 55, CR = 22, BB = { x: -5, y: 5 }, L1 = 58, L2 = 58;
  const rearSp = $("rearSpokes"), frontSp = $("frontSpokes"), ring = $("ring"), chain = $("chain");
  const nearCrank = $("nearCrank"), farCrank = $("farCrank"), nearPedal = $("nearPedal"), farPedal = $("farPedal");
  const nearLeg = $("nearLeg"), farLeg = $("farLeg"), nearFoot = $("nearFoot"), farFoot = $("farFoot");
  const pelican = $("pelican"), head = $("head"), pouch = $("pouch"), bag = $("bag"), pupil = $("pupil");
  const dustG = $("dust");
  const dust = [];

  function ik(hx, hy, fx, fy) {
    const dx = fx - hx, dy = fy - hy;
    let d = Math.hypot(dx, dy);
    d = Math.max(Math.abs(L1 - L2) + 0.5, Math.min(d, L1 + L2 - 0.5));
    const a = Math.atan2(dy, dx);
    const b = Math.acos((L1 * L1 + d * d - L2 * L2) / (2 * L1 * d));
    const ka = a - b; // 膝盖朝前
    return [hx + Math.cos(ka) * L1, hy + Math.sin(ka) * L1];
  }

  let t = 0, last = null, nextBlink = 2.2, blinkEnd = 0, dustAcc = 0;

  function frame(now) {
    if (last === null) last = now;
    const dt = Math.min(0.05, (now - last) / 1000);
    last = now;
    t += dt;
    const dist = t * SPEED;

    // 车轮
    const wheelA = dist / R;
    const wDeg = (wheelA * 180 / Math.PI) % 360;
    rearSp.setAttribute("transform", `rotate(${wDeg.toFixed(2)})`);
    frontSp.setAttribute("transform", `rotate(${wDeg.toFixed(2)})`);

    // 曲柄
    const cr = wheelA * 0.55;
    ring.setAttribute("transform", `rotate(${((cr * 180 / Math.PI) % 360).toFixed(2)})`);
    chain.setAttribute("stroke-dashoffset", ((cr * 11) % 50).toFixed(2));
    const pN = { x: BB.x + Math.cos(cr) * CR, y: BB.y + Math.sin(cr) * CR };
    const pF = { x: BB.x + Math.cos(cr + Math.PI) * CR, y: BB.y + Math.sin(cr + Math.PI) * CR };
    nearCrank.setAttribute("x1", BB.x); nearCrank.setAttribute("y1", BB.y);
    nearCrank.setAttribute("x2", pN.x.toFixed(2)); nearCrank.setAttribute("y2", pN.y.toFixed(2));
    farCrank.setAttribute("x1", BB.x); farCrank.setAttribute("y1", BB.y);
    farCrank.setAttribute("x2", pF.x.toFixed(2)); farCrank.setAttribute("y2", pF.y.toFixed(2));
    nearPedal.setAttribute("transform", `translate(${pN.x.toFixed(2)},${pN.y.toFixed(2)})`);
    farPedal.setAttribute("transform", `translate(${pF.x.toFixed(2)},${pF.y.toFixed(2)})`);

    // 身体起伏
    const bob = Math.sin(cr * 2) * 1.6;
    pelican.setAttribute("transform", `translate(0,${bob.toFixed(2)})`);

    // 腿（反向运动学）
    function leg(path, foot, hx, hy, p, phase) {
      const fy = p.y - 3;
      const [kx, ky] = ik(hx, hy, p.x, fy);
      path.setAttribute("d", `M${hx},${hy.toFixed(2)} L${kx.toFixed(2)},${ky.toFixed(2)} L${p.x.toFixed(2)},${fy.toFixed(2)}`);
      foot.setAttribute("transform", `translate(${p.x.toFixed(2)},${(p.y - 4).toFixed(2)}) rotate(${(Math.sin(cr + phase) * 12).toFixed(2)})`);
    }
    leg(nearLeg, nearFoot, -20, -84 + bob, pN, 0);
    leg(farLeg, farFoot, -30, -84 + bob, pF, Math.PI);

    // 头、喉囊、邮差包
    head.setAttribute("transform", `rotate(${(Math.sin(cr * 2 + 0.5) * 1.8).toFixed(2)} 12 -180)`);
    const ps = 1 + Math.sin(cr * 2 + 1.2) * 0.06;
    pouch.setAttribute("transform", `translate(48,-206) scale(1,${ps.toFixed(3)}) translate(-48,206)`);
    const sw = Math.sin(cr * 2 - 0.8) * 6 + Math.sin(t * 1.7) * 2;
    bag.setAttribute("transform", `rotate(${sw.toFixed(2)} -46 -102)`);

    // 眨眼
    if (t > nextBlink) { blinkEnd = t + 0.14; nextBlink = t + 2.5 + Math.random() * 2.5; }
    const sy = t < blinkEnd ? 0.12 : 1;
    pupil.setAttribute("transform", `translate(38,-216) scale(1,${sy}) translate(-38,216)`);

    // 视差图层
    for (const L of layers) {
      L.g.setAttribute("transform", `translate(${(-(dist * L.f % W)).toFixed(2)},0)`);
    }
    shoreG.setAttribute("transform", `translate(${(-(dist * 0.9 % SHORE_P)).toFixed(2)},${(Math.sin(t * 1.3) * 2.5).toFixed(2)})`);

    // 鱼
    for (const f of fishes) {
      f.x += (-SPEED * 0.38 + f.dir * f.sp) * dt;
      if (f.x < -40) { f.x = W + 40; f.y = 300 + Math.random() * 120; }
      if (f.x > W + 40) { f.x = -40; f.y = 300 + Math.random() * 120; }
      const yy = f.y + Math.sin(t * 1.5 + f.ph) * 4;
      f.g.setAttribute("transform", `translate(${f.x.toFixed(1)},${yy.toFixed(1)}) scale(${f.dir * f.s},${f.s})`);
      f.tail.setAttribute("transform", `rotate(${(Math.sin(t * 10 + f.ph) * 18).toFixed(1)} -8 0)`);
    }

    // 后轮扬起的细沙
    dustAcc += dt;
    while (dustAcc > 0.06) {
      dustAcc -= 0.06;
      const c = el("circle", { r: (1 + Math.random() * 2).toFixed(2), fill: Math.random() < 0.5 ? "#e6cf9f" : "#d4b886" }, dustG);
      dust.push({ c, x: 470 - 95 - 20 + Math.random() * 10, y: 454, vx: -SPEED * 0.35 - Math.random() * 40, vy: -20 - Math.random() * 40, life: 0, max: 0.5 + Math.random() * 0.4 });
    }
    for (let i = dust.length - 1; i >= 0; i--) {
      const p = dust[i];
      p.life += dt;
      p.vy += 140 * dt;
      p.x += p.vx * dt;
      p.y = Math.min(p.y + p.vy * dt, 456);
      if (p.life > p.max) { p.c.remove(); dust.splice(i, 1); continue; }
      p.c.setAttribute("cx", p.x.toFixed(1));
      p.c.setAttribute("cy", p.y.toFixed(1));
      p.c.setAttribute("opacity", (1 - p.life / p.max).toFixed(2));
    }

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
