  const e = document.createElementNS(NS, tag);
  for (const k in attrs) e.setAttribute(k, attrs[k]);
  return e;
}

// 浮标
const buoyColors = ['#e63946','#f4a261','#2a9d8f','#e9c46a','#457b9d','#f72585','#8338ec'];
const buoyG = document.getElementById('buoys');
for (let i = 0; i < 8; i++) {
  const x = 40 + rand() * 820;
  const y = 302 + rand() * 10;
  const color = buoyColors[Math.floor(rand() * buoyColors.length)];
  const pos = el('g', { transform: `translate(${x.toFixed(1)}, ${y.toFixed(1)})` });
  const bob = el('g', { class: 'buoy-bob', style: `animation-delay: ${(-rand()*2).toFixed(2)}s` });
  bob.appendChild(el('rect', { x: -2, y: -30, width: 4, height: 30, fill: '#f1faee' }));
  bob.appendChild(el('circle', { cx: 0, cy: 0, r: 7, fill: color, stroke: '#fff', 'stroke-width': 1.2 }));
  bob.appendChild(el('path', { d: `M2,-30 L 15,-23 L 2,-16 Z`, fill: color }));
  bob.appendChild(el('circle', { cx: 0, cy: 0, r: 2.2, fill: '#fff', opacity: 0.7 }));
  pos.appendChild(bob);
  buoyG.appendChild(pos);
}

// 雾气斑块
function makeMist(containerId, count, yRange, rRange, opacity) {
  const g = document.getElementById(containerId);
  for (let i = 0; i < count; i++) {
    const x = rand() * 900;
    const y = yRange[0] + rand() * (yRange[1] - yRange[0]);
    const rx = rRange[0] + rand() * (rRange[1] - rRange[0]);
    const ry = rx * (0.4 + rand() * 0.4);
    const e = el('ellipse', {
      cx: x.toFixed(1), cy: y.toFixed(1),
      rx: rx.toFixed(1), ry: ry.toFixed(1),
      fill: '#ffffff', opacity: opacity,
      filter: 'url(#mistBlur)'
    });
    e.setAttribute('class', 'mist-patch');
    e.style.animationDelay = (-rand() * 18).toFixed(2) + 's';
    e.style.animationDuration = (14 + rand() * 10).toFixed(2) + 's';
    g.appendChild(e);
  }
}
makeMist('mist', 9, [120, 260], [40, 90], 0.35);
makeMist('mistFront', 6, [230, 300], [50, 110], 0.22);

// 海鸥（简单）
const birdG = document.createElementNS(NS, 'g');
for (let i = 0; i < 5; i++) {
