    transform: `translate(${x.toFixed(1)},${y.toFixed(1)}) scale(${s.toFixed(2)})`,
    opacity: 0.8
  });
  birdG.appendChild(b);
}
document.getElementById('scene').insertBefore(birdG, document.getElementById('mistFront'));
</script>
