      el("line", { x1: 0, y1: 0, x2: (48 * Math.cos(a)).toFixed(2), y2: (48 * Math.sin(a)).toFixed(2), class: "spoke" }, g);
    }
    el("rect", { x: 30, y: -2.5, width: 9, height: 5, rx: 1.5, fill: "#ff7a00" }, g);
  });

  // 太阳光芒
  const rays = $("sunRays");
  for (let i = 0; i < 12; i++) {
    const a = i / 12 * Math.PI * 2;
    el("line", {
      x1: 655 + 46 * Math.cos(a), y1: 85 + 46 * Math.sin(a),
      x2: 655 + 60 * Math.cos(a), y2: 85 + 60 * Math.sin(a)
    }, rays);
  }

  // 海浪
  const waveDefs = [
    { y: 256, w: 1.5, op: .45, f: 0.04, amp: 2 },
    { y: 274, w: 2, op: .55, f: 0.07, amp: 2.5 },
    { y: 294, w: 2.2, op: .65, f: 0.11, amp: 3 }
  ];
  const waves = waveDefs.map(w => {
    let d = `M-100,${w.y} q12.5,${-w.amp} 25,0`;
    for (let i = 0; i < 40; i++) d += " t25,0";
    return Object.assign(el("path", { d, "stroke-width": w.w, opacity: w.op, "stroke-dasharray": "30 20" }, $("waves")), { cfg: w });
  });

  // 浪花
  (() => {
    let d = "M-100,309";
    for (let x = -100; x < 1000; x += 30) d += ` q7.5,-4 15,0 q7.5,4 15,0`;
    $("foam").setAttribute("d", d);
  })();

  // 栏杆
  const rail = $("rail");
  let rope = "M0,366";
  for (let x = 0; x <= 960; x += 120) {
    el("rect", { x: x - 4, y: 358, width: 8, height: 40, fill: "#8b5a2b" }, rail);
    el("rect", { x: x - 5.5, y: 354, width: 11, height: 5, rx: 1.5, fill: "#6e4420" }, rail);
    if (x < 960) rope += ` Q${x + 60},381 ${x + 120},366`;
  }
  el("path", { d: rope, fill: "none", stroke: "#e2cb93", "stroke-width": 3 }, rail);

  // 木板缝与螺栓
  const planks = $("planks");
  for (let x = 0; x <= 960; x += 40) {
    el("line", { x1: x, y1: 398, x2: x, y2: 408, stroke: "#9a6131", "stroke-width": 1.5 }, planks);
  }
  for (let x = 20; x <= 960; x += 80) {
    el("circle", { cx: x, cy: 414.5, r: 1.7, fill: "#5b3818" }, planks);
    el("circle", { cx: x, cy: 427.5, r: 1.7, fill: "#5b3818" }, planks);
  }
  // 支撑桩
  const supports = $("supports");
  for (let x = 70; x <= 1120; x += 160) {
    el("rect", { x, y: 434, width: 14, height: 70, fill: "#6e4420" }, supports);
    el("rect", { x: x + 2, y: 434, width: 3, height: 70, fill: "#7f522a" }, supports);
  }

  // 脚趾纹
  const toes = document.querySelector("#nearLeg .toes");
  [[4, 2, 18, 6], [4, 2, 12, 8], [4, 2, 6, 8]].forEach(p =>
    el("line", { x1: p[0], y1: p[1], x2: p[2], y2: p[3] }, toes));

  // ---------- 视差景物 ----------
  const scenery = [];
  const addUse = (id, parent, x, y, s, f, span) => {
    const u = el("use", { href: "#" + id }, parent);
    scenery.push({ u, x, y, s, f, span });
  };
  [[50, 70, 1], [330, 45, .7], [640, 105, .9], [950, 60, 1.2]].forEach(c =>
    addUse("cloud", $("clouds"), c[0], c[1], c[2], 0.08, 1200));

  const beach = $("beach");
  [
    ["palm", 60, 384, 1], ["starfish", 170, 390, 1], ["umbrella", 260, 374, 1],
    ["palm", 470, 378, .85], ["umbrella", 700, 372, .9], ["starfish", 790, 386, .8],
    ["palm", 900, 386, 1.1], ["umbrella", 1120, 376, 1], ["starfish", 1230, 392, 1.1]
  ].forEach(b => addUse(b[0], beach, b[1], b[2], b[3], 0.45, 1350));

  // 海鸥
  const gulls = [
    { x: 120, y: 60, v: 22, ph: 0 },
    { x: 160, y: 80, v: 22, ph: 1.3 },
    { x: 520, y: 40, v: 15, ph: 2.1 }
  ].map(g => Object.assign(g, { e: el("path", {}, $("gulls")) }));

  // 风线
  const speed = [];
  for (let i = 0; i < 7; i++) {
    speed.push({
      x: Math.random() * 800, y: 150 + Math.random() * 230,
      len: 25 + Math.random() * 40, v: 380 + Math.random() * 180,
      e: el("line", { "stroke-width": 1.5 + Math.random() * 1.5, opacity: .35 + Math.random() * .35 }, $("speedLines"))
    });
  }

  // ---------- 引用 ----------
  const rearRot = $("rearRot"), frontRot = $("frontRot");
  const chain = $("chain"), chainring = $("chainring"), sprocket = $("sprocket");
  const nearCrank = $("nearCrank"), farCrank = $("farCrank");
  const nearPedal = $("nearPedal"), farPedal = $("farPedal");
  const rider = $("rider"), head = $("head"), pouch = $("pouch"), eye = $("eye");
  const ribbon1 = $("ribbon1"), ribbon2 = $("ribbon2");
  const fishTail = $("fishTail"), boat = $("boat"), foam = $("foam");
  const planksG = $("planks"), supportsG = $("supports"), railG = $("rail");

  const legs = ["nearLeg", "farLeg"].map(id => {
    const g = $(id);
    return {
      thigh: g.querySelector(".thigh"), shin: g.querySelector(".shin"),
      knee: g.querySelector(".knee"), foot: g.querySelector(".foot"),
      toes: g.querySelector(".toes")
    };
  });

  const C = { x: 385, y: 350 };   // 曲柄中心
  const CRANK = 22;
  const HIP = { x: 374, y: 248 };
  const THIGH = 58, SHIN = 68;
  const WHEEL_R = 55;
  const SPEED = 150;              // 像素/秒

  function ik(hx, hy, fx, fy, a, b) {
    const dx = fx - hx, dy = fy - hy;
    let d = Math.hypot(dx, dy);
    d = Math.max(Math.abs(a - b) + 0.01, Math.min(a + b - 0.01, d));
    const base = Math.atan2(dy, dx);
    const cosA = (a * a + d * d - b * b) / (2 * a * d);
    const off = Math.acos(Math.max(-1, Math.min(1, cosA)));
    const ang = base - off;          // 膝盖朝前
    return [hx + a * Math.cos(ang), hy + a * Math.sin(ang)];
  }

  function setLine(l, x1, y1, x2, y2) {
    l.setAttribute("x1", x1.toFixed(2)); l.setAttribute("y1", y1.toFixed(2));
    l.setAttribute("x2", x2.toFixed(2)); l.setAttribute("y2", y2.toFixed(2));
  }

  function ribbonPath(len, yoff, phase, t) {
    const pts = [];
    for (let i = 0; i <= 12; i++) {
      const k = i / 12;
      const x = 415 - k * len;
      const y = 125 + yoff * k + Math.sin(t * 9 - i * 0.8 + phase) * 4.5 * k;
      pts.push(x.toFixed(1) + "," + y.toFixed(1));
    }
    return "M" + pts.join(" L");
  }

  // ---------- 动画循环 ----------
  let offset = 0, t = 0, last = performance.now(), paused = false;
  document.getElementById("scene").addEventListener("click", () => {
    paused = !paused;
    last = performance.now();
  });

  function frame(now) {
    const dt = paused ? 0 : Math.min(0.05, (now - last) / 1000);
    last = now;
    t += dt;
    offset += SPEED * dt;

    const wheel = offset / WHEEL_R;      // 弧度
    const crank = wheel / 1.8;           // 齿比
    const wDeg = wheel * 180 / Math.PI, cDeg = crank * 180 / Math.PI;

    rearRot.setAttribute("transform", `rotate(${wDeg})`);
    frontRot.setAttribute("transform", `rotate(${wDeg})`);
    sprocket.setAttribute("transform", `rotate(${wDeg} 300 345)`);
    chainring.setAttribute("transform", `rotate(${cDeg} 385 350)`);
    chain.style.strokeDashoffset = (-crank * 16).toFixed(2);

    // 骑行颠簸
    const bob = 1.6 * Math.sin(crank * 2);
    rider.setAttribute("transform", `translate(0,${bob.toFixed(2)})`);

    // 曲柄与脚踏
    const pedals = [crank, crank + Math.PI].map(a => ({
      x: C.x + CRANK * Math.cos(a), y: C.y + CRANK * Math.sin(a), a
    }));
    setLine(nearCrank, C.x, C.y, pedals[0].x, pedals[0].y);
    setLine(farCrank, C.x, C.y, pedals[1].x, pedals[1].y);
    nearPedal.setAttribute("x", (pedals[0].x - 10).toFixed(2));
    nearPedal.setAttribute("y", (pedals[0].y - 3.5).toFixed(2));
    farPedal.setAttribute("x", (pedals[1].x - 10).toFixed(2));
    farPedal.setAttribute("y", (pedals[1].y - 3.5).toFixed(2));

    // 双腿 IK
    const hipY = HIP.y + bob;
    pedals.forEach((p, i) => {
      const L = legs[i];
      const ax = p.x - 6, ay = p.y - 11;
      const [kx, ky] = ik(HIP.x, hipY, ax, ay, THIGH, SHIN);
      setLine(L.thigh, HIP.x, hipY, kx, ky);
      setLine(L.shin, kx, ky, ax, ay);
      L.knee.setAttribute("cx", kx.toFixed(2));
      L.knee.setAttribute("cy", ky.toFixed(2));
      const tilt = 8 * Math.sin(p.a);
      const tf = `translate(${ax.toFixed(2)},${ay.toFixed(2)}) rotate(${tilt.toFixed(2)} 6 8)`;
      L.foot.setAttribute("transform", tf);
      if (L.toes) L.toes.setAttribute("transform", tf);
    });

    // 头部、喉囊、眨眼、飘带
    head.setAttribute("transform", `rotate(${(Math.sin(t * 2.2) * 2).toFixed(2)} 434 145)`);
    const ps = 1 + 0.05 * Math.sin(t * 7);
    pouch.setAttribute("transform", `translate(452 150) scale(1 ${ps.toFixed(3)}) translate(-452 -150)`);
    const blink = (t % 3.7) < 0.13 ? 0.1 : 1;
    eye.setAttribute("transform", `translate(442 133) scale(1 ${blink}) translate(-442 -133)`);
    ribbon1.setAttribute("d", ribbonPath(44, 5, 0, t));
    ribbon2.setAttribute("d", ribbonPath(37, 14, 1.4, t));

    // 小鱼尾巴
    fishTail.setAttribute("transform", `rotate(${(Math.sin(t * 10) * 12).toFixed(2)} 494 252)`);

    // 太阳
    rays.setAttribute("transform", `rotate(${(t * 8).toFixed(2)} 655 85)`);

    // 视差景物
    scenery.forEach(s => {
      const x = mod(s.x - offset * s.f, s.span) - 150;
      s.u.setAttribute("transform", `translate(${x.toFixed(2)},${s.y}) scale(${s.s})`);
    });

    // 海浪 / 浪花
    waves.forEach(w => {
      const x = -mod(offset * w.cfg.f + t * 6, 50);
      w.setAttribute("transform", `translate(${x.toFixed(2)},${(Math.sin(t * 1.5 + w.cfg.y) * 1.2).toFixed(2)})`);
    });
    foam.setAttribute("transform",
      `translate(${(-mod(offset * 0.3, 30)).toFixed(2)},${(Math.sin(t * 1.8) * 2).toFixed(2)})`);

    // 帆船
    boat.setAttribute("transform",
      `translate(${(mod(620 - t * 7, 1000) - 100).toFixed(2)},${(262 + Math.sin(t * 1.6) * 1.5).toFixed(2)}) rotate(${(Math.sin(t * 1.6) * 3).toFixed(2)})`);

    // 木栈道滚动
    planksG.setAttribute("transform", `translate(${(-mod(offset, 80)).toFixed(2)},0)`);
    supportsG.setAttribute("transform", `translate(${(-mod(offset, 160)).toFixed(2)},0)`);
    railG.setAttribute("transform", `translate(${(-mod(offset, 120)).toFixed(2)},0)`);

    // 海鸥
    gulls.forEach(g => {
      const x = mod(g.x - t * g.v, 1000) - 100;
      const y = g.y + Math.sin(t * 1.2 + g.ph) * 6;
      const tip = -2 + 6 * Math.sin(t * 7 + g.ph);
      g.e.setAttribute("d", `M-12,${tip.toFixed(2)} Q-6,-5 0,0 Q6,-5 12,${tip.toFixed(2)}`);
      g.e.setAttribute("transform", `translate(${x.toFixed(2)},${y.toFixed(2)})`);
    });

    // 风线
    speed.forEach(s => {
      s.x -= s.v * dt;
      if (s.x + s.len < 0) {
        s.x = 800 + Math.random() * 200;
        s.y = 150 + Math.random() * 230;
      }
      setLine(s.e, s.x, s.y, s.x + s.len, s.y);
    });

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
</body>
</html>
```

## 画面内容

**主角鹈鹕**
- 头上戴着白顶、深蓝帽檐的水手帽，帽顶有红色绒球，两条蓝色飘带会随海风摆动。
- 长长的黄色喙下挂着橙色喉囊，会随骑行轻轻晃动。
- 会眨眼，头部也会轻微摆动。
- 一只翅膀握着车把，翅尖是黑色的。
- 双腿用两段关节模型实时计算位置，蹼足会一直踩在**橙色脚踏**上。

**自行车**
- 车架为薄荷绿色，前后轮和辐条会转动。
- 链条、牙盘和飞轮都会同步转动。
- 车筐里放着一条小鱼，鱼尾会摆动。

**夏日沙滩步道场景**
- 太阳的光芒缓慢旋转，白云和海鸥在天上飘过。
- 海面有海浪和闪光，远处有带灯塔的小岛，还有一艘帆船在摇晃。
- 沙滩上有棕榈树、遮阳伞和海星，棕榈叶会随海风摇摆。
- 前景是木栈道和绳索栏杆，按视差滚动，营造骑行前进的感觉。
- 空中有白色风线，表现海风和速度感。

