  c.style.animationDelay = (Math.random() * 3) + 's';
  c.style.animationDuration = (1.5 + Math.random() * 2) + 's';
  sp.appendChild(c);
}

let t = 0, last = performance.now();
const crank = document.getElementById('crank');
const rearSpokes = document.getElementById('rearSpokes');
const frontSpokes = document.getElementById('frontSpokes');
const pelican = document.getElementById('pelican');
const wing = document.getElementById('wing');
const bell = document.getElementById('bell');
const legL1 = document.getElementById('legL1');
const legL2 = document.getElementById('legL2');
const legR1 = document.getElementById('legR1');
const legR2 = document.getElementById('legR2');
const footL = document.getElementById('footL');
const footR = document.getElementById('footR');

function knee(hip, foot) {
  const mx = (hip.x + foot.x) / 2;
  const my = (hip.y + foot.y) / 2;
  const dx = foot.x - hip.x, dy = foot.y - hip.y;
  const len = Math.hypot(dx, dy) || 1;
  const nx = -dy / len, ny = dx / len;
  const bend = 18;
  return { x: mx + nx * bend, y: my + ny * bend };
}

function setLine(el, a, b) {
  el.setAttribute('x1', a.x); el.setAttribute('y1', a.y);
  el.setAttribute('x2', b.x); el.setAttribute('y2', b.y);
}

function loop(now) {
  const dt = (now - last) / 1000; last = now;
  t += dt;
  const speed = 2.2;
  const a = t * speed;
  const deg = a * 180 / Math.PI;

  crank.setAttribute('transform', `translate(450,393) rotate(${deg})`);
  rearSpokes.setAttribute('transform', `rotate(${deg})`);
  frontSpokes.setAttribute('transform', `rotate(${deg})`);

  const cx = 450, cy = 393, r = 28;
  const pedalR = { x: cx + r * Math.cos(a), y: cy + r * Math.sin(a) };
  const pedalL = { x: cx + r * Math.cos(a + Math.PI), y: cy + r * Math.sin(a + Math.PI) };

  const bob = Math.sin(a * 2) * 3;
  pelican.setAttribute('transform', `translate(410,${300 + bob})`);

  const flap = Math.sin(t * 6) * 25;
  wing.setAttribute('transform', `translate(-8,0) rotate(${flap})`);

  const swing = Math.sin(t * 4) * 8;
  bell.setAttribute('transform', `translate(505,318) rotate(${swing})`);

  const hipL = { x: 395, y: 315 + bob };
  const hipR = { x: 425, y: 315 + bob };

  const kL = knee(hipL, pedalL);
  const kR = knee(hipR, pedalR);

  setLine(legL1, hipL, kL);
  setLine(legL2, kL, pedalL);
  setLine(legR1, hipR, kR);
  setLine(legR2, kR, pedalR);

  footL.setAttribute('cx', pedalL.x); footL.setAttribute('cy', pedalL.y);
  footR.setAttribute('cx', pedalR.x); footR.setAttribute('cy', pedalR.y);

  requestAnimationFrame(loop);
}
requestAnimationFrame(loop);
</script>
