  const cloudLayer = document.getElementById("cloudLayer");

  function makeCloud(x, y, s) {
    const g = el("g", { transform: "translate(" + x + "," + y + ") scale(" + s + ")" }, cloudLayer);
    const blobs = [
      [  0,   0, 46, 26],
      [ 42,   6, 36, 22],
      [-42,   8, 32, 20],
      [ 12, -18, 32, 22],
      [-16, -14, 28, 18]
    ];
    for (let i = 0; i < blobs.length; i++) {
      const b = blobs[i];
      el("ellipse", {
        cx: b[0], cy: b[1], rx: b[2], ry: b[3],
        fill: "#ffffff", opacity: "0.92"
      }, g);
    }
    return g;
  }

  // 位置按 1000 的周期平铺，保证循环无缝
  makeCloud(  150,  92, 1.00);
  makeCloud(  470,  62, 0.72);
  makeCloud(  780, 118, 0.88);
  makeCloud( 1150,  92, 1.00);
  makeCloud( 1470,  62, 0.72);
  makeCloud( 1780, 118, 0.88);

  /* ============================================================
     2. 海面波纹
     ============================================================ */
  const waveLayer = document.getElementById("waveLayer");
  for (let i = 0; i < 11; i++) {
    const y = 344 + Math.random() * 40;
    const x = Math.random() * 1000;
    const w = 30 + Math.random() * 60;
    el("path", {
      d: "M " + x + " " + y + " q " + (w / 2) + " -6 " + w + " 0",
      "stroke-width": (1.6 + Math.random() * 1.8).toFixed(1),
      opacity: (0.3 + Math.random() * 0.45).toFixed(2)
    }, waveLayer);
  }

  /* ============================================================
     3. 椰子树
     ============================================================ */
  const palmLayer = document.getElementById("palms");

  function makePalm(x, y, s) {
    const g = el("g", { transform: "translate(" + x + "," + y + ") scale(" + s + ")" }, palmLayer);

    // 树干
    el("path", {
      d: "M2 4 Q -8 -80 -18 -158",
      stroke: "#8b5a32", "stroke-width": 18,
      fill: "none", "stroke-linecap": "round"
    }, g);

    el("path", {
      d: "M0 0 Q -10 -80 -20 -158",
      stroke: "#bd8752", "stroke-width": 10,
      fill: "none", "stroke-linecap": "round"
    }, g);

    // 树冠（外层定位 + 内层摆动）
    const wrap = el("g", { transform: "translate(-20,-158)" }, g);
    const top = el("g", {}, wrap);

    el("animateTransform", {
      attributeName: "transform",
      type: "rotate",
      values: "-3;-1;1.5;3.5;1.5;-1;-3",
      dur: "6.5s",
      repeatCount: "indefinite"
    }, top);

    const fronds = [
      [-110, -46],
      [ -80, -98],
      [ -22, -124],
      [  44, -110],
      [  98, -62],
      [ 106,   8],
      [  56,   56],
      [ -64,   48]
    ];

    for (let i = 0; i < fronds.length; i++) {
      const tx = fronds[i][0];
      const ty = fronds[i][1];
      const len = Math.hypot(tx, ty) || 1;

      // 法线方向，用于让叶片鼓起
      const nx = -ty / len;
      const ny =  tx / len;

      const mx = tx * 0.5, my = ty * 0.5;

      const c1x = mx + nx * 26, c1y = my + ny * 26;
      const c2x = mx - nx * 5,  c2y = my - ny * 5;

      el("path", {
        d: "M0 0 Q " + c1x.toFixed(1) + " " + c1y.toFixed(1) + " " + tx + " " + ty +
           " Q " + c2x.toFixed(1) + " " + c2y.toFixed(1) + " 0 0 Z",
        fill: (i % 2 === 0) ? "#2d874d" : "#40a862"
      }, top);
    }

    el("circle", { r: 12, fill: "#7a5330" }, top);
    el("circle", { r: 6.5, fill: "#926539" }, top);

    return g;
  }

  makePalm(  74, 430, 0.78);
  makePalm( 214, 430, 0.55);
  makePalm( 836, 430, 0.90);
  makePalm( 962, 430, 0.62);

  /* ============================================================
     4. 速度线
     ============================================================ */
  const speedLines = document.getElementById("speedLines");
  for (let i = 0; i < 8; i++) {
    const y = 455 + Math.random() * 160;
    const len = 45 + Math.random() * 95;
    const x = 1020 + Math.random() * 220;
    const ln = el("line", {
      x1: x, y1: y, x2: x + len, y2: y,
      opacity: (0.25 + Math.random() * 0.4).toFixed(2)
    }, speedLines);
    ln.style.animation =
      "zip " + (0.85 + Math.random() * 0.8).toFixed(2) + "s linear " +
      (Math.random() * 2.2).toFixed(2) + "s infinite";
  }

  /* ============================================================
     5. 骑行系统
     ============================================================ */
  const wheelRear  = document.getElementById("wheelRear");
  const wheelFront = document.getElementById("wheelFront");
  const crank      = document.getElementById("crank");
  const rider      = document.getElementById("rider");
  const roadDash   = document.getElementById("roadDash");

  const scarfTailA = document.getElementById("scarfTailA");
  const scarfTailB = document.getElementById("scarfTailB");

  const legs = {
    front: {
      hip:  document.getElementById("thighFront"),
      shin: document.getElementById("shinFront"),
      foot: document.getElementById("footFront")
    },
    back: {
      hip:  document.getElementById("thighBack"),
      shin: document.getElementById("shinBack"),
      foot: document.getElementById("footBack")
    }
  };

  // ---- 骨骼参数 ----
  const REAR  = { x: 420, y: 545 };
  const FRONT = { x: 580, y: 545 };
  const BB    = { x: 492, y: 524 };
  const CRANK_R = 24;
  const HIP   = { x: 462, y: 448 };
  const THIGH_LEN = 56;
  const SHIN_LEN  = 56;

  const RAD = Math.PI / 180;
  const DEG = 180 / Math.PI;

  function clamp(v, a, b) { return v < a ? a : (v > b ? b : v); }

  /**
   * 两段式反向运动学：髋关节固定，脚落在踏板上，求膝盖位置。
   */
  function solveKnee(hip, foot, l1, l2) {
    const dx = foot.x - hip.x;
    const dy = foot.y - hip.y;
    const d  = Math.max(Math.hypot(dx, dy), 0.001);
    const base = Math.atan2(dy, dx);

    // 余弦定理
    const cosT = clamp((l1 * l1 + d * d - l2 * l2) / (2 * l1 * d), -1, 1);
    const t = Math.acos(cosT);

    // 膝盖向前（屏幕右侧）弯
    const ka = base - t;

    return {
      x: hip.x + l1 * Math.cos(ka),
      y: hip.y + l1 * Math.sin(ka)
    };
  }

  function pedalPos(ang) {
    return {
      x: BB.x + CRANK_R * Math.cos(ang),
      y: BB.y + CRANK_R * Math.sin(ang)
    };
  }

  function updateLeg(leg, pedal, footRx, footRy) {
    const knee = solveKnee(HIP, pedal, THIGH_LEN, SHIN_LEN);

    leg.hip.setAttribute("x1", HIP.x);
    leg.hip.setAttribute("y1", HIP.y);
    leg.hip.setAttribute("x2", knee.x.toFixed(1));
    leg.hip.setAttribute("y2", knee.y.toFixed(1));

    leg.shin.setAttribute("x1", knee.x.toFixed(1));
    leg.shin.setAttribute("y1", knee.y.toFixed(1));
    leg.shin.setAttribute("x2", pedal.x.toFixed(1));
    leg.shin.setAttribute("y2", pedal.y.toFixed(1));

    leg.foot.setAttribute("cx", pedal.x.toFixed(1));
    leg.foot.setAttribute("cy", (pedal.y + 2).toFixed(1));
    leg.foot.setAttribute("rx", footRx);
    leg.foot.setAttribute("ry", footRy);
  }

  /**
   * 围巾飘带：沿直线采样，叠加两组衰减的正弦波。
   */
  function buildTail(x0, y0, x1, y1, amp, time, phase) {
    const N = 26;
    let d = "M " + x0 + " " + y0;

    for (let i = 1; i <= N; i++) {
      const s = i / N;

      const x = x0 + (x1 - x0) * s;
      const yBase = y0 + (y1 - y0) * s;

      // 越靠尾端摆动越大
      const env = Math.pow(s, 0.75);

      const wave =
        Math.sin(s * 5.4 - time * 7.4 + phase) * amp * env +
        Math.sin(s * 10.8 - time * 11.6 + phase * 2.1) * amp * 0.30 * env;

      d += " L " + x.toFixed(1) + " " + (yBase + wave).toFixed(1);
    }

    return d;
  }

  /* ============================================================
     6. 主动画循环
     ============================================================ */
  let last = 0;
  let aWheel = 0;
  let aCrank = 0;
  let tAccum = 0;

  // 车轮周长 ≈ 327px；让车轮角速度与路面虚线滚动速度匹配
  const WHEEL_SPEED = 10.2;   // rad/s
  const CRANK_SPEED =  7.0;   // rad/s

  function frame(now) {
    if (!last) last = now;

    let dt = (now - last) / 1000;
    if (dt > 0.06) dt = 0.06;   // 防止切页签回来时瞬移
    last = now;

    tAccum += dt;

    aWheel += dt * WHEEL_SPEED;
    aCrank += dt * CRANK_SPEED;

    const wheelDeg = aWheel * DEG;
    const crankDeg = aCrank * DEG;

    /* ---- 车轮 ---- */
    wheelRear.setAttribute(
      "transform",
      "translate(" + REAR.x + "," + REAR.y + ") rotate(" + wheelDeg.toFixed(1) + ")"
    );
    wheelFront.setAttribute(
      "transform",
      "translate(" + FRONT.x + "," + FRONT.y + ") rotate(" + wheelDeg.toFixed(1) + ")"
    );

    /* ---- 曲柄 ---- */
    crank.setAttribute(
      "transform",
      "translate(" + BB.x + "," + BB.y + ") rotate(" + crankDeg.toFixed(1) + ")"
    );

    /* ---- 双腿 ---- */
    const pedalFront = pedalPos(aCrank);
    const pedalBack  = pedalPos(aCrank + Math.PI);

    updateLeg(legs.front, pedalFront, 13, 7.5);
    updateLeg(legs.back,  pedalBack,  12, 7);

    /* ---- 车身上下微颠 ---- */
    const bob = Math.sin(tAccum * 7.6) * 1.8 + Math.sin(tAccum * 13.1) * 0.7;
    rider.setAttribute("transform", "translate(0," + bob.toFixed(2) + ")");

    /* ---- 路面虚线滚动（与车轮同速） ---- */
    // 车轮周长 = 2π·52 ≈ 327px，每秒转过 327 * (WHEEL_SPEED / 2π) px
    const pxPerSec = 52 * WHEEL_SPEED;           // ≈ 530 px/s
    roadDash.style.strokeDashoffset = (-tAccum * pxPerSec).toFixed(1);

    /* ---- 围巾 ---- */
    scarfTailA.setAttribute(
      "d",
      buildTail(478, 338, 236, 300, 22, tAccum, 0)
    );
    scarfTailB.setAttribute(
      "d",
      buildTail(482, 350, 272, 356, 16, tAccum, 2.35)
    );

    requestAnimationFrame(frame);
  }

  requestAnimationFrame(frame);

})();
</script>
</body>
