  </g>
  <ellipse id="footL" cx="422" cy="385" rx="9" ry="4.5" fill="#ff9f43" stroke="#e67e22" stroke-width="0.8"/>
  <ellipse id="footR" cx="478" cy="385" rx="9" ry="4.5" fill="#ff9f43" stroke="#e67e22" stroke-width="0.8"/>
</svg>
