<script>
  const rearSpokes = document.getElementById('rearSpokes');
  const frontSpokes = document.getElementById('frontSpokes');
  const pedals = document.getElementById('pedals');
  const pelicanBody = document.getElementById('pelicanBody');
  const wing = document.getElementById('wing');
  const legL = document.getElementById('legL');
  const legR = document.getElementById('legR');
  const footL = document.getElementById('footL');
  const footR = document.getElementById('footR');
  const waveGroup = document.getElementById('waveGroup');

  const crankX = 450;
  const crankY = 385;
  const pedalRadius = 28;
  const hipLBase = { x: 415, y: 305 };
  const hipRBase = { x: 435, y: 305 };

  let start = null;
  const speed = 3.6; // radians per second

  function animate(timestamp) {
    if (!start) start = timestamp;
    const t = (timestamp - start) / 1000;
    const angle = t * speed;

    // Rotate wheels and pedals
    const deg = angle * 180 / Math.PI;
    rearSpokes.setAttribute('transform', `rotate(${deg} 390 385)`);
    frontSpokes.setAttribute('transform', `rotate(${deg} 510 385)`);
    pedals.setAttribute('transform', `rotate(${deg} ${crankX} ${crankY})`);

    // Pelican body bob
    const bob = Math.sin(angle) * 4.5;
    pelicanBody.setAttribute('transform', `translate(0 ${bob})`);

    // Wing flap
    const flap = Math.sin(angle * 2) * 13;
    wing.setAttribute('transform', `rotate(${flap} 405 282)`);

    // Pedal positions
    const pL = {
      x: crankX + pedalRadius * Math.cos(angle + Math.PI),
      y: crankY + pedalRadius * Math.sin(angle + Math.PI)
    };
    const pR = {
      x: crankX + pedalRadius * Math.cos(angle),
      y: crankY + pedalRadius * Math.sin(angle)
    };

    const hipL = { x: hipLBase.x, y: hipLBase.y + bob };
    const hipR = { x: hipRBase.x, y: hipRBase.y + bob };

    legL.setAttribute('x1', hipL.x);
    legL.setAttribute('y1', hipL.y);
    legL.setAttribute('x2', pL.x);
    legL.setAttribute('y2', pL.y);

    legR.setAttribute('x1', hipR.x);
    legR.setAttribute('y1', hipR.y);
    legR.setAttribute('x2', pR.x);
    legR.setAttribute('y2', pR.y);

    footL.setAttribute('cx', pL.x);
    footL.setAttribute('cy', pL.y);
    footR.setAttribute('cx', pR.x);
    footR.setAttribute('cy', pR.y);

    // Waves
    const waveOffset = (t * 55) % 120;
    waveGroup.setAttribute('transform', `translate(${waveOffset} 0)`);

    requestAnimationFrame(animate);
  }

  requestAnimationFrame(animate);
</script>
