<script>
  // 生成辐条
  function makeSpokes(groupId, cx, cy) {
    const g = document.getElementById(groupId);
    for (let i = 0; i < 12; i++) {
      const ang = i * 30 * Math.PI / 180;
      const x = cx + 55 * Math.cos(ang);
      const y = cy + 55 * Math.sin(ang);
      const line = document.createElementNS('http://www.w3.org/2000/svg', 'line');
      line.setAttribute('x1', cx);
      line.setAttribute('y1', cy);
      line.setAttribute('x2', x);
      line.setAttribute('y2', y);
      line.setAttribute('stroke', '#888');
      line.setAttribute('stroke-width', '1.2');
      g.appendChild(line);
    }
  }
  makeSpokes('rearSpokes', 260, 420);
  makeSpokes('frontSpokes', 460, 420);

  const crankLeft = document.getElementById('crankLeft');
  const crankRight = document.getElementById('crankRight');
  const pedalLeft = document.getElementById('pedalLeft');
  const pedalRight = document.getElementById('pedalRight');
  const rearWheel = document.getElementById('rearWheel');
  const frontWheel = document.getElementById('frontWheel');
  const bellSwing = document.getElementById('bellSwing');
  const wingGroup = document.getElementById('wingGroup');
  const thighLeft = document.getElementById('thighLeft');
  const calfLeft = document.getElementById('calfLeft');
  const thighRight = document.getElementById('thighRight');
  const calfRight = document.getElementById('calfRight');

  const Cx = 360, Cy = 390, R = 42;
  const hipLeft = { x: 305, y: 295 };
  const hipRight = { x: 325, y: 295 };
  const L1 = 55, L2 = 55;

  function deg(r) { return r * 180 / Math.PI; }

  function solveLeg(thighEl, calfEl, fx, fy) {
    const dx = fx, dy = fy;
    let d = Math.hypot(dx, dy);
    const minD = Math.abs(L1 - L2) + 1;
    const maxD = L1 + L2 - 1;
    d = Math.max(minD, Math.min(maxD, d));
    const a = Math.atan2(dy, dx);
    let cos1 = (L1 * L1 + d * d - L2 * L2) / (2 * L1 * d);
    cos1 = Math.max(-1, Math.min(1, cos1));
    const ang1 = Math.acos(cos1);
    // 选择膝盖更低的解
    const t1 = a - ang1;
    const t2 = a + ang1;
    const thighAngle = (Math.sin(t1) > Math.sin(t2)) ? t1 : t2;
    const kneeX = L1 * Math.cos(thighAngle);
    const kneeY = L1 * Math.sin(thighAngle);
    const calfAngle = Math.atan2(fy - kneeY, fx - kneeX);
    thighEl.setAttribute('transform', `rotate(${deg(thighAngle)})`);
    calfEl.setAttribute('transform', `translate(${L1},0) rotate(${deg(calfAngle - thighAngle)})`);
  }

  let crankAngle = 0;
  let time = 0;

  function frame() {
    crankAngle += 0.05;
    time += 0.05;

    const leftPedalAngle = crankAngle;
    const rightPedalAngle = crankAngle + Math.PI;

    const pl = { x: Cx + R * Math.cos(leftPedalAngle), y: Cy + R * Math.sin(leftPedalAngle) };
    const pr = { x: Cx + R * Math.cos(rightPedalAngle), y: Cy + R * Math.sin(rightPedalAngle) };

    // 曲柄旋转
    crankLeft.setAttribute('transform', `rotate(${deg(leftPedalAngle)})`);
    crankRight.setAttribute('transform', `rotate(${deg(rightPedalAngle)})`);
    // 踏板保持水平
    pedalLeft.setAttribute('transform', `translate(42,0) rotate(${-deg(leftPedalAngle)})`);
    pedalRight.setAttribute('transform', `translate(42,0) rotate(${-deg(rightPedalAngle)})`);

    // 车轮旋转（与曲柄联动）
    const wheelAngle = -crankAngle * 2.2;
    rearWheel.setAttribute('transform', `rotate(${deg(wheelAngle)} 260 420)`);
    frontWheel.setAttribute('transform', `rotate(${deg(wheelAngle)} 460 420)`);

    // 铜车铃摆动
    const swing = 12 * Math.sin(time * 3.2);
    bellSwing.setAttribute('transform', `rotate(${swing})`);

    // 翅膀扇动
    const flap = 14 * Math.sin(time * 2.4);
    wingGroup.setAttribute('transform', `translate(290,260) rotate(${flap}) translate(-290,-260)`);

    // 腿部 IK
    solveLeg(thighLeft, calfLeft, pl.x - hipLeft.x, pl.y - hipLeft.y);
    solveLeg(thighRight, calfRight, pr.x - hipRight.x, pr.y - hipRight.y);

    requestAnimationFrame(frame);
  }

  frame();
</script>
</body>
</html>
